const midwestWestItineraries=[{"id":"twin-cities-mn-city","title":"Minneapolis\u2013Saint Paul, MN: Four-Day City Adventure","destination":"Minneapolis\u2013Saint Paul, MN","state":"MN","stateName":"Minnesota","region":"Twin Cities","days":4,"tripType":"city adventure","interests":["family","museums","food","amusement-parks"],"budget":1400,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days, excluding lodging upgrades.","tagline":"Two downtowns, one giant mall, and a zoo \u2014 the Twin Cities pack a whole vacation into one metro.","overview":"Minneapolis and Saint Paul sit side by side on the Mississippi, and together they make one of the most family-friendly city trips in the Midwest. Ride roller coasters inside the country's biggest mall, come nose-to-nose with grizzlies at the Minnesota Zoo, and dig into dinosaur fossils at a museum overlooking the river. Between the two downtowns you'll find skyways, riverfront trails, and more kid-approved food than you can finish. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride coasters indoors at Nickelodeon Universe inside Mall of America","Meet grizzly bears, moose, and penguins at the Minnesota Zoo","Ride the Flour Tower through a historic Minneapolis mill","Free world-class art at the Minneapolis Institute of Art","Walk the Stone Arch Bridge over the Mississippi at sunset"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 4+. Stroller-friendly throughout; the zoo and mall involve lots of walking, so plan midday breaks.","lat":44.97902,"lng":-93.26494,"itinerary":[{"day":1,"title":"Mall of America Day","morning":{"stop":"Mall of America","description":"Arrive early and head straight for Nickelodeon Universe, the huge indoor theme park in the center of the mall. Hit the family coasters before the crowds, then wander the mall's four floors \u2014 kids love the giant LEGO store and the M&M's store.","cost":"Free entry; ride wristbands from $39.99/person (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"SEA LIFE Minnesota Aquarium","description":"Inside the mall, walk through the 300-foot ocean tunnel as sharks and sea turtles glide overhead. The touch pools and the seahorse kingdom keep younger kids busy for a solid hour or two.","cost":"$27.99/adult, $21.99/child (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Dinner and the Mall After Dark","description":"Grab an early dinner at one of the mall's sit-down spots, then let the kids burn off energy with a few more rides \u2014 evenings are usually quieter. Head back to your hotel before the little ones crash.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo Day in Apple Valley","morning":{"stop":"Minnesota Zoo","description":"Drive 20 minutes south to the Minnesota Zoo, one of the country's best. Start on the Northern Trail to see grizzly bears, moose, and wolverines, then warm up in the Tropics Trail with monkeys and tropical birds.","cost":"$24.95/adult, $16.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Minnesota Zoo \u2014 Discovery Bay and farm","description":"After lunch at the zoo's caf\u00e9, visit Discovery Bay's penguins, sharks, and touch pools. Finish at the Wells Fargo Family Farm, where kids can pet goats and watch cow-milking demos in season.","cost":"Included with admission (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Bloomington","description":"Head back toward your hotel and grab a relaxed dinner \u2014 the area around the mall is full of family restaurants. Early bedtime after a full zoo day is a win.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Saint Paul: Science and the Capitol","morning":{"stop":"Science Museum of Minnesota","description":"Perched above the Mississippi in downtown St. Paul, this museum is a kid magnet: a 75-foot dinosaur skeleton, a real mummy, and hands-on experiment galleries. Don't miss the Mississippi River views from the upper floors.","cost":"$24.95/adult, $16.95/child (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Minnesota State Capitol","description":"A short drive away, the golden-domed Capitol offers free guided tours (est.) past marble staircases and the famous quadriga statues. Kids get a kick out of spotting the golden horses on the roof.","cost":"Free tours (est.)","time":"2:00 PM \u2013 3:30 PM"},"evening":{"stop":"Grand Avenue stroll and dinner","description":"Wander Grand Avenue's shops and caf\u00e9s, then settle in for dinner at a classic St. Paul spot. The avenue's old-timey feel is a nice change of pace from the mall crowds.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":4,"title":"Minneapolis Riverfront and Art","morning":{"stop":"Mill City Museum","description":"Built into the ruins of a historic flour mill, this museum's highlight is the Flour Tower \u2014 an elevator ride that drops you through eight floors of milling history with booming sound effects kids love.","cost":"$16/adult, $8/child (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Minneapolis Institute of Art","description":"One of the country's best free art museums. The Asian art wing and the period rooms hold kids' attention, and the family guides turn a gallery visit into a scavenger hunt.","cost":"Free general admission (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Stone Arch Bridge at sunset","description":"End the trip with a walk across the Stone Arch Bridge as the sun sets behind the Minneapolis skyline. It's the perfect family photo spot \u2014 and a calm, easy finale before the drive home.","cost":"Free (est.)","time":"6:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Mall of America","description":"The largest shopping and entertainment complex in the country, anchored by Nickelodeon Universe \u2014 a full indoor theme park \u2014 plus SEA LIFE Minnesota Aquarium, mini golf, and hundreds of stores. You could easily spend two days here and not see it all.","officialUrl":"https://www.mallofamerica.com","price":"Free entry; Nickelodeon Universe wristbands from $39.99/person (est.)","photos":["assets/midwest-west/twin-cities-mn-city/attr1-1.jpg","assets/midwest-west/twin-cities-mn-city/attr1-2.jpg","assets/midwest-west/twin-cities-mn-city/attr1-3.jpg","assets/midwest-west/twin-cities-mn-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mall%20of%20America%20Bloomington%20MN"},{"name":"Minnesota Zoo","description":"A top-tier zoo set on 485 acres of rolling Minnesota landscape. The Northern Trail showcases cold-climate animals like grizzlies, Amur tigers, and moose, while indoor trails bring the tropics and an aquarium's worth of sea life year-round.","officialUrl":"https://mnzoo.org","price":"$24.95/adult, $16.95/child (est.)","photos":["assets/midwest-west/twin-cities-mn-city/attr2-1.jpg","assets/midwest-west/twin-cities-mn-city/attr2-2.jpg","assets/midwest-west/twin-cities-mn-city/attr2-3.jpg","assets/midwest-west/twin-cities-mn-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Minnesota%20Zoo%20Apple%20Valley%20MN"},{"name":"Science Museum of Minnesota","description":"Overlooking the Mississippi in downtown St. Paul, this hands-on museum packs in a 75-foot Diplodocus skeleton, real Egyptian mummies, and floors of experiments kids can touch. The omnitheater films are worth the add-on ticket.","officialUrl":"https://www.smm.org","price":"$24.95/adult, $16.95/child (est.)","photos":["assets/midwest-west/twin-cities-mn-city/attr3-1.jpg","assets/midwest-west/twin-cities-mn-city/attr3-2.jpg","assets/midwest-west/twin-cities-mn-city/attr3-3.jpg","assets/midwest-west/twin-cities-mn-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Science%20Museum%20of%20Minnesota%20St.%20Paul%20MN"},{"name":"Mill City Museum","description":"Housed in the ruins of the world's largest flour mill, this museum tells the story of how Minneapolis became the flour capital of the world. The Flour Tower ride and the rooftop observation deck over St. Anthony Falls are the highlights.","officialUrl":"https://www.millcitymuseum.org","price":"$16/adult, $8/child (est.)","photos":["assets/midwest-west/twin-cities-mn-city/attr4-1.jpg","assets/midwest-west/twin-cities-mn-city/attr4-2.jpg","assets/midwest-west/twin-cities-mn-city/attr4-3.jpg","assets/midwest-west/twin-cities-mn-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mill%20City%20Museum%20Minneapolis%20MN"},{"name":"Minneapolis Institute of Art","description":"A world-class art museum with free general admission, holding everything from ancient artifacts to modern masterpieces. The kid-friendly guides and hands-on family days make it surprisingly fun for children.","officialUrl":"https://artsmia.org","price":"Free general admission (est.)","photos":["assets/midwest-west/twin-cities-mn-city/attr5-1.jpg","assets/midwest-west/twin-cities-mn-city/attr5-2.jpg","assets/midwest-west/twin-cities-mn-city/attr5-3.jpg","assets/midwest-west/twin-cities-mn-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Minneapolis%20Institute%20of%20Art%20Minneapolis%20MN"}],"restaurants":[{"name":"Matt's Bar","detail":"The Minneapolis institution behind the Jucy Lucy \u2014 a burger with molten cheese stuffed inside \u2014 in a no-frills neighborhood bar kids will remember.","price":"$$"},{"name":"Kramarczuk's Sausage Co.","detail":"A St. Paul Eastern European deli and sausage shop on the edge of downtown; grab sausages, pierogi, and pastries at the counter.","price":"$"},{"name":"Cossetta's","detail":"A sprawling St. Paul Italian food hall with pizza, pasta, and a pasticceria \u2014 easy to please every eater in the family.","price":"$$"}],"rainyDay":["Mall of America \u2014 a full indoor theme park, aquarium, and mini golf under one roof","Science Museum of Minnesota \u2014 hands-on exhibits and an omnitheater in downtown St. Paul","Minneapolis Institute of Art \u2014 free galleries that easily fill a rainy afternoon"],"driveNotes":"Fly into MSP airport, right next to the Mall of America, or drive in on I-35W or I-94. The light rail connects the airport, Mall of America, and both downtowns, so you can skip a rental car if you stay near a station. Parking downtown runs $10\u2013$20/day (est.); the zoo and mall have free lots.","related":["des-moines-ia-city","rochester-mn-city","kansas-city-mo-city"],"imageAsset":"assets/midwest-west/twin-cities-mn-city/hero.jpg"},{"id":"duluth-mn-northshore","title":"Duluth, MN: Three-Day Lakeside Adventure","destination":"Duluth, MN","state":"MN","stateName":"Minnesota","region":"North Shore","days":3,"tripType":"lakeside adventure","interests":["family","outdoors","nature","scenic"],"budget":950,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Waterfalls, a lighthouse on the cliffs, and the biggest lake in the world \u2014 the North Shore is pure family magic.","overview":"Duluth sits at the tip of Lake Superior, and the North Shore drive up its coast is one of America's great family road trips. You'll chase waterfalls at Gooseberry Falls, tour a lighthouse perched on a cliff, and watch thousand-foot freighters glide under the Aerial Lift Bridge. Pack layers \u2014 Superior's breeze keeps things cool even in July \u2014 and plan for at least one famous North Shore sunset. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk behind the cascades at Gooseberry Falls State Park","Tour Split Rock Lighthouse, the most photographed spot in Minnesota","Watch giant ships pass under Duluth's Aerial Lift Bridge","Touch stingrays at the Great Lakes Aquarium","Drive the scenic North Shore past cliffs and cobblestone beaches"],"bestSeason":"June\u2013October","familyFriendly":"Best for ages 5+. Waterfall trails are short but can be slippery \u2014 wear grippy shoes and keep little ones close at overlooks.","lat":46.78796,"lng":-92.09985,"itinerary":[{"day":1,"title":"Duluth Harbor Day","morning":{"stop":"Canal Park & Aerial Lift Bridge","description":"Start on Duluth's waterfront boardwalk and time your visit to watch the 100-year-old Aerial Lift Bridge rise for a passing freighter \u2014 the ship schedule is posted nearby. Kids love the sandy beach and the pier lighthouse at the end of the breakwater.","cost":"Free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Great Lakes Aquarium","description":"Right in Canal Park, this aquarium focuses on the Great Lakes watershed: sturgeon, lake trout, and a two-story hands-on water play area. The stingray touch tank and the shipwreck exhibits are the standouts.","cost":"$24/adult, $16/child (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Dinner in Canal Park","description":"Pick a family-friendly spot along the waterfront \u2014 many have patios facing the harbor. After dinner, stroll the Lakewalk as the sun drops over the lake.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Waterfalls and the Lighthouse","morning":{"stop":"Gooseberry Falls State Park","description":"Drive 40 minutes up the North Shore to Minnesota's most beloved waterfall park. The paved trails to the Upper, Middle, and Lower Falls are short and stroller-friendly, and kids can scramble on the basalt rocks at the base of the falls.","cost":"$7/day vehicle permit (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Split Rock Lighthouse State Park","description":"Ten minutes farther north, tour the 1910 lighthouse standing on a 133-foot cliff above Superior. The visitor center's film and the climb to the light are worth it; the shoreline trail below gives the classic postcard view.","cost":"$7/day vehicle permit + $10/adult lighthouse tour (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Drive back to Duluth","description":"Stop at one of the roadside smoked-fish shops on the way back, then have a low-key dinner in Duluth. The kids will sleep well after a day of trails and cliffs.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Tettegouche and the Drive Home","morning":{"stop":"Tettegouche State Park","description":"Continue up the shore to Tettegouche, the wildest-feeling of the North Shore parks. The short hike to the sea cave overlook and Shovel Point's clifftop views are unforgettable, and the Palisade Head pulloff nearby is a must-stop.","cost":"$7/day vehicle permit (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Lunch and agate hunting","description":"Grab lunch in the tiny town of Silver Bay, then stop at a cobblestone beach to hunt for Lake Superior agates \u2014 the kids' souvenir hunt of the trip. Every beach has different stones, so try two.","cost":"$40\u2013$60 lunch for four (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Return to Duluth","description":"Drive back down the shore with one last stop at a scenic overlook. If you have energy, catch the sunset from Enger Tower above the city \u2014 the whole harbor spreads out below you.","cost":"Free (est.)","time":"4:30 PM \u2013 7:00 PM"}}],"attractions":[{"name":"Gooseberry Falls State Park","description":"Minnesota's most-visited state park, where the Gooseberry River tumbles over basalt ledges in three dramatic sets of falls. Paved, accessible trails make the waterfalls easy for all ages, and the visitor center has great hands-on exhibits about the North Shore.","officialUrl":"https://www.dnr.state.mn.us/state_parks/park.html?id=spk00172","price":"$7/day vehicle permit (est.)","photos":["assets/midwest-west/duluth-mn-northshore/attr1-1.jpg","assets/midwest-west/duluth-mn-northshore/attr1-2.jpg","assets/midwest-west/duluth-mn-northshore/attr1-3.jpg","assets/midwest-west/duluth-mn-northshore/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Gooseberry%20Falls%20State%20Park%20Two%20Harbors%20MN"},{"name":"Split Rock Lighthouse State Park","description":"The iconic 1910 lighthouse on a 133-foot cliff is the most photographed landmark in Minnesota. Tour the keeper's house and climb the tower, then hike the shoreline trail for the classic view of the light above the crashing waves.","officialUrl":"https://www.dnr.state.mn.us/state_parks/park.html?id=spk00275","price":"$7/day vehicle permit; lighthouse tours $10/adult (est.)","photos":["assets/midwest-west/duluth-mn-northshore/attr2-1.jpg","assets/midwest-west/duluth-mn-northshore/attr2-2.jpg","assets/midwest-west/duluth-mn-northshore/attr2-3.jpg","assets/midwest-west/duluth-mn-northshore/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Split%20Rock%20Lighthouse%20State%20Park%20Two%20Harbors%20MN"},{"name":"Great Lakes Aquarium","description":"Duluth's waterfront aquarium tells the story of the Great Lakes watershed, from playful river otters to lake sturgeon and a touchable stingray pool. The two-story water-play area lets kids dam, divert, and splash like engineers.","officialUrl":"https://glaquarium.org","price":"$24/adult, $16/child (est.)","photos":["assets/midwest-west/duluth-mn-northshore/attr3-1.jpg","assets/midwest-west/duluth-mn-northshore/attr3-2.jpg","assets/midwest-west/duluth-mn-northshore/attr3-3.jpg","assets/midwest-west/duluth-mn-northshore/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Great%20Lakes%20Aquarium%20Duluth%20MN"},{"name":"Canal Park & Aerial Lift Bridge","description":"Duluth's lively waterfront district, where the century-old Aerial Lift Bridge rises 135 feet to let thousand-foot freighters pass beneath. Walk the Lakewalk, visit the lighthouse pier, and watch the ships come in from the observation areas.","officialUrl":"https://www.visitduluth.com","price":"Free (est.)","photos":["assets/midwest-west/duluth-mn-northshore/attr4-1.jpg","assets/midwest-west/duluth-mn-northshore/attr4-2.jpg","assets/midwest-west/duluth-mn-northshore/attr4-3.jpg","assets/midwest-west/duluth-mn-northshore/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Canal%20Park%20%26%20Aerial%20Lift%20Bridge%20Duluth%20MN"},{"name":"Tettegouche State Park","description":"The North Shore's wild child: sea caves, the clifftop Shovel Point, and the Inland Sea views from Palisade Head. Trails range from easy overlooks to rugged cliff hikes, and the Baptism River's High Falls reward the longer walk.","officialUrl":"https://www.dnr.state.mn.us/state_parks/park.html?id=spk00286","price":"$7/day vehicle permit (est.)","photos":["assets/midwest-west/duluth-mn-northshore/attr5-1.jpg","assets/midwest-west/duluth-mn-northshore/attr5-2.jpg","assets/midwest-west/duluth-mn-northshore/attr5-3.jpg","assets/midwest-west/duluth-mn-northshore/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tettegouche%20State%20Park%20Silver%20Bay%20MN"}],"restaurants":[{"name":"Grandma's Saloon & Grill","detail":"A Duluth institution on the waterfront serving burgers, walleye, and pasta in a lively saloon setting the kids will love.","price":"$$"},{"name":"Northern Waters Smokehaus","detail":"A tiny counter in the DeWitt-Seitz Marketplace famous for smoked fish sandwiches \u2014 grab lunch to eat on the Lakewalk.","price":"$"},{"name":"Duluth Grill","detail":"A cheerful, family-run spot in a former warehouse with creative breakfasts and comfort-food dinners.","price":"$$"}],"rainyDay":["Great Lakes Aquarium \u2014 stingrays, otters, and an indoor water-play area","Lake Superior Railroad Museum \u2014 climb aboard historic trains at the Duluth Depot","Duluth Children's Museum \u2014 hands-on play for the under-10 crowd"],"driveNotes":"Duluth is about 2.5 hours north of Minneapolis on I-35. The North Shore drive (Highway 61) is the main event \u2014 allow extra time for the many scenic pulloffs, and fill up gas in Duluth or Two Harbors since stations thin out north of there. State park vehicle permits are $7/day or $35/year (est.).","related":["brainerd-mn-lakes","voyageurs-mn-nature","twin-cities-mn-city"],"imageAsset":"assets/midwest-west/duluth-mn-northshore/hero.jpg"},{"id":"brainerd-mn-lakes","title":"Brainerd, MN: Three-Day Lake Getaway","destination":"Brainerd, MN","state":"MN","stateName":"Minnesota","region":"Brainerd Lakes","days":3,"tripType":"lake getaway","interests":["family","outdoors","amusement-parks","beaches"],"budget":900,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Classic Minnesota lake country: sandy beaches by day, mini golf and Paul Bunyan by night.","overview":"The Brainerd Lakes Area is Minnesota's quintessential summer playground \u2014 more than 400 lakes surrounded by pines, resorts, and old-school family attractions. Spend your days swimming and boating on Gull Lake, your afternoons at a wildlife park or arboretum, and your evenings at mini golf or saying hi to a 30-foot-tall talking lumberjack. It's an easy, unhurried trip built for kids. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Meet the 30-foot talking Paul Bunyan at Paul Bunyan Land","Swim and boat on the sandy shores of Gull Lake","Hand-feed giraffes at Safari North Wildlife Park","Wander 500 acres of gardens and trails at Northland Arboretum","Evening mini golf and go-karts, lake-country style"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 3+. Lake beaches are shallow and sandy; bring life jackets for boat days and bug spray for wooded trails.","lat":46.35349,"lng":-94.20069,"itinerary":[{"day":1,"title":"Paul Bunyan and the Lake","morning":{"stop":"Paul Bunyan Land","description":"This old-school amusement park is pure Minnesota nostalgia: rides for little kids, a pioneer village, and the famous 30-foot animatronic Paul Bunyan who greets visitors by name. Arrive at opening to ride everything before lunch.","cost":"$22/person (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Gull Lake beach afternoon","description":"Cool off at one of Gull Lake's public beaches \u2014 the sand is soft and the water stays shallow a long way out, perfect for young swimmers. Bring a picnic or grab sandwiches from a lakeside deli.","cost":"Free; picnic $30\u2013$40 (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Mini golf on the strip","description":"The Brainerd lakes area is mini-golf heaven. Pick one of the big themed courses along Highway 371, then grab ice cream on the way back to your cabin or hotel.","cost":"$10\u2013$12/person mini golf (est.)","time":"6:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Wildlife and Gardens","morning":{"stop":"Safari North Wildlife Park","description":"A drive-and-walk wildlife park where you can feed giraffes, watch bears, and ride a camel. The park is compact enough for little legs, and the animal encounters feel personal, not theme-parky.","cost":"$19.95/adult, $14.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Northland Arboretum","description":"Five hundred acres of gardens, prairie, and pine forest with easy walking trails. Kids love the fairy garden trail and the pond full of frogs; the visitor center has scavenger-hunt sheets.","cost":"$5/person (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Brainerd","description":"Head into Brainerd for dinner \u2014 the downtown has come a long way, with family-friendly grills and breweries. An early night sets you up for the boat day tomorrow.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 7:30 PM"}},{"day":3,"title":"Boats and State Park","morning":{"stop":"Morning on Gull Lake","description":"Rent a pontoon for a half day \u2014 no experience needed, and the rental outfits give you a quick lesson. Cruise the lake, find a quiet bay to swim, and let the kids take turns 'driving' under supervision.","cost":"$200\u2013$300 half-day pontoon rental (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Crow Wing State Park","description":"Twenty minutes south, this park sits where the Crow Wing River meets the Mississippi. Walk the short trail to the historic townsite, climb the overlook, and let the kids wade at the river confluence.","cost":"$7/day vehicle permit (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell dinner on the water","description":"End the trip at a lakeside restaurant with a patio over the water. Watch the boats come in as the sun sets \u2014 the classic Brainerd goodbye.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Paul Bunyan Land","description":"A beloved old-fashioned amusement park starring a 30-foot talking Paul Bunyan who has greeted kids since the 1950s. Rides skew young, the pioneer village is charming, and the whole place runs on pure nostalgia.","officialUrl":"https://paulbunyanland.com","price":"$22/person (est.)","photos":["assets/midwest-west/brainerd-mn-lakes/attr1-1.jpg","assets/midwest-west/brainerd-mn-lakes/attr1-2.jpg","assets/midwest-west/brainerd-mn-lakes/attr1-3.jpg","assets/midwest-west/brainerd-mn-lakes/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Paul%20Bunyan%20Land%20Brainerd%20MN"},{"name":"Safari North Wildlife Park","description":"An interactive wildlife park where the animals come to you \u2014 feed giraffes by hand, watch big cats, and take a camel ride. It's smaller and more personal than a big-city zoo, which families tend to love.","officialUrl":"https://www.safarinorth.com","price":"$19.95/adult, $14.95/child (est.)","photos":["assets/midwest-west/brainerd-mn-lakes/attr2-1.jpg","assets/midwest-west/brainerd-mn-lakes/attr2-2.jpg","assets/midwest-west/brainerd-mn-lakes/attr2-3.jpg","assets/midwest-west/brainerd-mn-lakes/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Safari%20North%20Wildlife%20Park%20Brainerd%20MN"},{"name":"Northland Arboretum","description":"Over 500 acres of gardens, restored prairie, and pine forest laced with easy trails. The children's garden, pond life, and seasonal events make it a calm, pretty counterpoint to the area's busier attractions.","officialUrl":"https://www.northlandarb.org","price":"$5/person (est.)","photos":["assets/midwest-west/brainerd-mn-lakes/attr3-1.jpg","assets/midwest-west/brainerd-mn-lakes/attr3-2.jpg","assets/midwest-west/brainerd-mn-lakes/attr3-3.jpg","assets/midwest-west/brainerd-mn-lakes/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Northland%20Arboretum%20Brainerd%20MN"},{"name":"Gull Lake","description":"The centerpiece of the Brainerd Lakes Area: 9,400 acres of clear water with sandy public beaches, marinas, and lakeside restaurants. Swim, rent a pontoon, or just watch the sunset from a dock \u2014 this is what lake country is all about.","officialUrl":"https://www.visitbrainerd.com","price":"Free; boat rentals from $200/half day (est.)","photos":["assets/midwest-west/brainerd-mn-lakes/attr4-1.jpg","assets/midwest-west/brainerd-mn-lakes/attr4-2.jpg","assets/midwest-west/brainerd-mn-lakes/attr4-3.jpg","assets/midwest-west/brainerd-mn-lakes/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Gull%20Lake%20Brainerd%20MN"},{"name":"Crow Wing State Park","description":"Where the Crow Wing River joins the Mississippi, this park mixes history and nature: the site of a frontier town, an oxcart trail, and quiet riverside trails. It's an easy half-day trip and rarely crowded.","officialUrl":"https://www.dnr.state.mn.us/state_parks/park.html?id=spk00115","price":"$7/day vehicle permit (est.)","photos":["assets/midwest-west/brainerd-mn-lakes/attr5-1.jpg","assets/midwest-west/brainerd-mn-lakes/attr5-2.jpg","assets/midwest-west/brainerd-mn-lakes/attr5-3.jpg","assets/midwest-west/brainerd-mn-lakes/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Crow%20Wing%20State%20Park%20Brainerd%20MN"}],"restaurants":[{"name":"Prairie Bay Grill & Catering","detail":"An upscale-casual lakeside grill on Gull Lake with a big patio \u2014 great for a nicer family dinner over the water.","price":"$$"},{"name":"Sawmill Inn","detail":"A classic Brainerd supper-club-style spot known for hearty portions, Friday fish fry, and a cozy northwoods feel.","price":"$$"},{"name":"Ernie's on Gull Lake","detail":"A casual lakeside bar and grill where you can dock your boat or grab a burger after the beach.","price":"$$"}],"rainyDay":["Minnesota Military Museum \u2014 tanks, planes, and hands-on history at Camp Ripley (Little Falls)","Charles A. Lindbergh House and Museum \u2014 the aviator's boyhood home on the Mississippi (Little Falls)","Pine Grove Zoo \u2014 a small, walkable zoo that's easy to do between showers (Little Falls)"],"driveNotes":"Brainerd is about 2 hours north of Minneapolis on Highway 371. Summer weekends bring heavy cabin traffic \u2014 arrive Friday before 3 PM or after 7 PM if you can. Most resorts and rentals are on Gull Lake's east side; grocery shop in Brainerd before heading to a cabin. Pontoon rentals book out weeks ahead in July.","related":["duluth-mn-northshore","okoboji-ia-lakes","lake-ozarks-mo-lake"],"imageAsset":"assets/midwest-west/brainerd-mn-lakes/hero.jpg"},{"id":"rochester-mn-city","title":"Rochester, MN: Two-Day Weekend Getaway","destination":"Rochester, MN","state":"MN","stateName":"Minnesota","region":"Southeast Minnesota","days":2,"tripType":"weekend getaway","interests":["family","museums","nature"],"budget":550,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"A relaxed small-city weekend: nature trails, a free zoo, and the lake famous for its giant geese.","overview":"Rochester is best known for the Mayo Clinic, but families know it as one of Minnesota's easiest weekend trips: everything is close, parking is painless, and several of the best attractions are free. Hike the trails at Quarry Hill, meet bison at a free zoo, and watch hundreds of giant Canada geese glide into Silver Lake at dusk. It's a low-key, low-stress two days. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Explore limestone caves at Quarry Hill Nature Center","See bison, wolves, and mountain lions free at Zollman Zoo","Watch the famous giant geese land on Silver Lake","Hands-on art at the Rochester Art Center","Tour the historic Plummer House and its gardens"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 4+. Quarry Hill's cave tours have low spots kids love; the whole weekend is stroller-friendly.","lat":44.01932,"lng":-92.45893,"itinerary":[{"day":1,"title":"Nature Day","morning":{"stop":"Quarry Hill Nature Center","description":"Start at this 320-acre nature preserve in the middle of the city. Tour the sandstone cave (kids love the low, twisty passages), visit the live-animal room, and walk the pond trails looking for turtles and herons.","cost":"Free; cave tours $5/person (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Oxbow Park & Zollman Zoo","description":"Twenty minutes northwest, this county park pairs hiking trails with a free native-animals zoo. Bison, elk, wolves, and cougars live in naturalistic enclosures, and the trails along the Zumbro River are lovely.","cost":"Free (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner downtown","description":"Head back to Rochester for dinner \u2014 the downtown near the Mayo campus has plenty of family options. Take an evening stroll along the Zumbro River paths if the kids still have energy.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Art, Gardens, and Geese","morning":{"stop":"Rochester Art Center","description":"On the riverfront downtown, this modern art center is small enough for kids and runs great family workshops. The interactive exhibits change often, so check what's on before you go.","cost":"$8/adult, kids often free (est.)","time":"10:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Plummer House","description":"Tour the 1917 English Tudor mansion built by Mayo Clinic co-founder Dr. Henry Plummer. The gardens, greenhouse, and water tower are fun to explore, and the guided tour is full of good stories.","cost":"$5/person tours (est.)","time":"1:00 PM \u2013 3:00 PM"},"evening":{"stop":"Silver Lake Park at dusk","description":"End the weekend at Silver Lake, where hundreds of giant Canada geese \u2014 some weighing 20 pounds \u2014 come gliding in at dusk. It's one of Minnesota's oddest and most memorable wildlife sights, and it's free.","cost":"Free (est.)","time":"5:00 PM \u2013 7:00 PM"}}],"attractions":[{"name":"Quarry Hill Nature Center","description":"A 320-acre nature preserve with a historic sandstone cave, live native animals, and miles of trails through woods and prairie. The guided cave tours and the nature center's hands-on exhibits make it Rochester's top family stop.","officialUrl":"https://www.qhnc.org","price":"Free; cave tours $5/person (est.)","photos":["assets/midwest-west/rochester-mn-city/attr1-1.jpg","assets/midwest-west/rochester-mn-city/attr1-2.jpg","assets/midwest-west/rochester-mn-city/attr1-3.jpg","assets/midwest-west/rochester-mn-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Quarry%20Hill%20Nature%20Center%20Rochester%20MN"},{"name":"Oxbow Park & Zollman Zoo","description":"A county park combining river trails, campgrounds, and a free zoo of Minnesota native animals \u2014 bison, wolves, cougars, otters, and eagles. It's an easy, uncrowded half-day that costs nothing.","officialUrl":"https://www.olmstedcounty.gov","price":"Free (est.)","photos":["assets/midwest-west/rochester-mn-city/attr2-1.jpg","assets/midwest-west/rochester-mn-city/attr2-2.jpg","assets/midwest-west/rochester-mn-city/attr2-3.jpg","assets/midwest-west/rochester-mn-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Oxbow%20Park%20%26%20Zollman%20Zoo%20Byron%20MN"},{"name":"Rochester Art Center","description":"A striking modern building on the Zumbro River housing contemporary art with a strong family program. Small enough to enjoy in an hour or two, with workshops and interactive exhibits aimed at kids.","officialUrl":"https://www.rochesterartcenter.org","price":"$8/adult, kids often free (est.)","photos":["assets/midwest-west/rochester-mn-city/attr3-1.jpg","assets/midwest-west/rochester-mn-city/attr3-2.jpg","assets/midwest-west/rochester-mn-city/attr3-3.jpg","assets/midwest-west/rochester-mn-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rochester%20Art%20Center%20Rochester%20MN"},{"name":"Silver Lake Park","description":"Rochester's beloved city lake, famous for its resident flock of giant Canada geese \u2014 among the largest in the world. Walk the lakeside trail, rent a paddleboat in summer, and come at dusk to watch the geese come in.","officialUrl":"https://www.rochestermn.gov","price":"Free (est.)","photos":["assets/midwest-west/rochester-mn-city/attr4-1.jpg","assets/midwest-west/rochester-mn-city/attr4-2.jpg","assets/midwest-west/rochester-mn-city/attr4-3.jpg","assets/midwest-west/rochester-mn-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Silver%20Lake%20Park%20Rochester%20MN"},{"name":"Plummer House","description":"The 1917 Tudor-style mansion of Mayo Clinic pioneer Dr. Henry Plummer, set on 65 acres of gardens. Guided tours reveal secret passages and medical-history stories; the grounds alone are worth the visit.","officialUrl":"https://www.rochestermn.gov","price":"$5/person tours (est.)","photos":["assets/midwest-west/rochester-mn-city/attr5-1.jpg","assets/midwest-west/rochester-mn-city/attr5-2.jpg","assets/midwest-west/rochester-mn-city/attr5-3.jpg","assets/midwest-west/rochester-mn-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Plummer%20House%20Rochester%20MN"}],"restaurants":[{"name":"Newt's","detail":"A Rochester burger-and-sandwich institution since the 1940s; the half-pound burgers and crinkle fries please every age.","price":"$"},{"name":"Canadian Honker","detail":"A cozy, family-run spot in a historic building serving comfort food \u2014 famous for its chicken wild rice soup.","price":"$$"},{"name":"Whistle Binkies on the Lake","detail":"Casual lakeside dining with a big deck overlooking the water; burgers, walleye, and live music in summer.","price":"$$"}],"rainyDay":["Rochester Art Center \u2014 family workshops and changing exhibits downtown","History Center of Olmsted County \u2014 local history with a kid-friendly touch","Quarry Hill Nature Center \u2014 indoor live-animal exhibits and cave tours run rain or shine"],"driveNotes":"Rochester is 90 minutes south of Minneapolis on Highway 52. Downtown parking is easy and cheap, and most attractions are 10\u201315 minutes apart. If you're combining this with the Twin Cities, Rochester makes a relaxed add-on weekend \u2014 or a calm home base with cheaper hotels.","related":["twin-cities-mn-city","des-moines-ia-city","iowa-city-ia-college"],"imageAsset":"assets/midwest-west/rochester-mn-city/hero.jpg"},{"id":"voyageurs-mn-nature","title":"Voyageurs, MN: Three-Day Wilderness Adventure","destination":"International Falls, MN","state":"MN","stateName":"Minnesota","region":"Voyageurs","days":3,"tripType":"wilderness adventure","interests":["family","outdoors","nature","scenic"],"budget":800,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"A national park you explore by boat \u2014 loons, eagles, and water as far as you can see.","overview":"Voyageurs National Park is one of America's least-visited national parks, and that's exactly its charm: 218,000 acres of lakes, islands, and forest on the Canadian border, best explored by boat. Base yourself in International Falls, take a ranger boat tour to a historic fishing camp, and fall asleep to loon calls. This is a trip for families who like their nature big and their crowds small. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Take a ranger-led boat tour deep into Voyageurs National Park","Visit the historic Kettle Falls Hotel, reachable only by water","See the whimsical Ellsworth Rock Gardens by boat","Listen for loons and watch for eagles on Rainy Lake","Pose with the giant Smokey Bear in International Falls"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 6+. Boat tours are the main event \u2014 bring layers, snacks, and life jackets for kids (provided on tours).","lat":48.6026,"lng":-93.40368,"itinerary":[{"day":1,"title":"Rainy Lake Introduction","morning":{"stop":"Voyageurs National Park \u2014 Rainy Lake Visitor Center","description":"Start at the park's main visitor center on Rainy Lake. Watch the orientation film, explore the exhibits on voyageur fur traders, and walk the short overlook trail. Rangers can help you pick the right boat tour for your kids' ages.","cost":"Free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Rainy Lake by boat","description":"Rent a boat or join an afternoon ranger cruise. Rainy Lake's 227,000 acres are dotted with islands \u2014 keep eyes peeled for bald eagles, otters, and loons. Swimming off a quiet island beach is the classic Voyageurs afternoon.","cost":"Ranger tours $35/adult, $18/child; boat rentals from $150/half day (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Smokey Bear Park","description":"Back in International Falls, visit Smokey Bear Park to see the 26-foot Smokey statue \u2014 the town's beloved landmark. Grab dinner nearby and turn in early; the northwoods gets dark and quiet fast.","cost":"Free; dinner $50\u2013$70 for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Kettle Falls Expedition","morning":{"stop":"Boat to Kettle Falls","description":"Take the ranger boat tour (or your rental boat) across Rainy and Namakan Lakes to Kettle Falls. The journey itself is the adventure \u2014 miles of island-dotted water with not another soul in sight.","cost":"Ranger tour $45/adult, $22/child (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Kettle Falls Hotel","description":"Have lunch at the historic Kettle Falls Hotel, a 1910 wilderness lodge reachable only by boat or floatplane. Tour the old saloon with its tilted floor, then hike the short portage trail between the lakes.","cost":"$15\u2013$20/person lunch (est.)","time":"12:30 PM \u2013 3:30 PM"},"evening":{"stop":"Sunset on the water","description":"On the boat ride back, watch the sun drop behind the islands \u2014 Voyageurs sunsets are spectacular. Back in town, a casual dinner and an early night.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":3,"title":"Rock Gardens and Farewell","morning":{"stop":"Ellsworth Rock Gardens","description":"Boat to the Kabetogama Peninsula to see Jack Ellsworth's astonishing rock sculptures \u2014 dozens of terraces and flower beds built from lake stone in the 1940s\u201360s. Rangers lead short walks explaining this one-of-a-kind folk-art site.","cost":"Free; ranger programs free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Last swim and picnic","description":"Find a final island beach for a swim and a picnic lunch. Let the kids skip stones and hunt for agates while you soak in the quiet \u2014 it's the perfect slow goodbye to the park.","cost":"Free; picnic $30\u2013$40 (est.)","time":"12:30 PM \u2013 3:00 PM"},"evening":{"stop":"Dinner in International Falls","description":"One last northwoods dinner in town. If the sky is clear, step outside after dark \u2014 the stars this far north, away from city lights, are incredible.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Voyageurs National Park \u2014 Rainy Lake Visitor Center","description":"The gateway to Minnesota's only national park: exhibits on fur-trade voyageurs, a theater film, ranger programs, and the docks where boat tours depart. Start every Voyageurs trip here.","officialUrl":"https://www.nps.gov/voya","price":"Free (est.)","photos":["assets/midwest-west/voyageurs-mn-nature/attr1-1.jpg","assets/midwest-west/voyageurs-mn-nature/attr1-2.jpg","assets/midwest-west/voyageurs-mn-nature/attr1-3.jpg","assets/midwest-west/voyageurs-mn-nature/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Voyageurs%20National%20Park%20%E2%80%94%20Rainy%20Lake%20Visitor%20Center%20International%20Falls%20MN"},{"name":"Kettle Falls","description":"A historic dam and portage between Rainy and Namakan Lakes, home to the 1910 Kettle Falls Hotel. Reachable only by boat, it's the quintessential Voyageurs expedition \u2014 book the ranger tour or rent a boat.","officialUrl":"https://www.nps.gov/voya","price":"Free; ranger boat tours $45/adult, $22/child (est.)","photos":["assets/midwest-west/voyageurs-mn-nature/attr2-1.jpg","assets/midwest-west/voyageurs-mn-nature/attr2-2.jpg","assets/midwest-west/voyageurs-mn-nature/attr2-3.jpg","assets/midwest-west/voyageurs-mn-nature/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kettle%20Falls%20International%20Falls%20MN"},{"name":"Ellsworth Rock Gardens","description":"A folk-art wonder: Chicago carpenter Jack Ellsworth spent 20 summers building terraces, sculptures, and flower beds from lake rock on a remote island. Accessible by boat, with ranger walks in summer.","officialUrl":"https://www.nps.gov/voya","price":"Free (est.)","photos":["assets/midwest-west/voyageurs-mn-nature/attr3-1.jpg","assets/midwest-west/voyageurs-mn-nature/attr3-2.jpg","assets/midwest-west/voyageurs-mn-nature/attr3-3.jpg","assets/midwest-west/voyageurs-mn-nature/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ellsworth%20Rock%20Gardens%20International%20Falls%20MN"},{"name":"Rainy Lake","description":"One of the great border lakes: 227,000 acres of clear water, 2,500 islands, and shoreline shared with Canada. Boat, fish, swim, and watch for moose, eagles, and loons \u2014 it's the heart of the park.","officialUrl":"https://www.nps.gov/voya","price":"Free; boat rentals from $150/half day (est.)","photos":["assets/midwest-west/voyageurs-mn-nature/attr4-1.jpg","assets/midwest-west/voyageurs-mn-nature/attr4-2.jpg","assets/midwest-west/voyageurs-mn-nature/attr4-3.jpg","assets/midwest-west/voyageurs-mn-nature/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Rainy%20Lake%20International%20Falls%20MN"},{"name":"Smokey Bear Park","description":"International Falls' beloved riverfront park, home to the 26-foot Smokey Bear statue that's been greeting visitors since 1954. A playground, picnic areas, and river views make it a perfect evening stop.","officialUrl":"https://www.ci.international-falls.mn.us/","price":"Free (est.)","photos":["assets/midwest-west/voyageurs-mn-nature/attr5-1.jpg","assets/midwest-west/voyageurs-mn-nature/attr5-2.jpg","assets/midwest-west/voyageurs-mn-nature/attr5-3.jpg","assets/midwest-west/voyageurs-mn-nature/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Smokey%20Bear%20Park%20International%20Falls%20MN"}],"restaurants":[{"name":"Chocolate Moose","detail":"A lodge-style family restaurant with big portions of comfort food \u2014 burgers, wild rice soup, and breakfast all day.","price":"$$"},{"name":"Coffee Landing Cafe","detail":"A cozy downtown caf\u00e9 with excellent coffee, pastries, and light lunches \u2014 the town's favorite morning stop.","price":"$"},{"name":"Thunderbird Lodge","detail":"A classic northwoods lodge restaurant on Rainy Lake serving walleye, steaks, and burgers with a view of the water.","price":"$$"}],"rainyDay":["Rainy Lake Visitor Center \u2014 films, exhibits, and ranger talks indoors","Bronko Nagurski Museum \u2014 the football legend's hometown museum in Smokey Bear Park","Backus Community Center \u2014 local events, classes, and a historic theater in International Falls"],"driveNotes":"International Falls is 4.5 hours north of Minneapolis on Highway 53 \u2014 a long but scenic drive. Gas up before the final stretch; services thin out north of Virginia, MN. The park is boat-access only beyond the visitor centers, so book ranger boat tours weeks ahead in summer. Bring bug spray \u2014 the northwoods mosquitoes are legendary in June.","related":["duluth-mn-northshore","sandhills-ne-nature","brainerd-mn-lakes"],"imageAsset":"assets/midwest-west/voyageurs-mn-nature/hero.jpg"},{"id":"des-moines-ia-city","title":"Des Moines, IA: Three-Day City Adventure","destination":"Des Moines, IA","state":"IA","stateName":"Iowa","region":"Central Iowa","days":3,"tripType":"city adventure","interests":["family","museums","food","amusement-parks"],"budget":950,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"A capital city that punches above its weight: a golden dome, a great zoo, and coasters 15 minutes away.","overview":"Des Moines is one of the Midwest's most underrated family cities \u2014 clean, compact, and full of surprises. Tour a gleaming golden-domed Capitol, wander a tropical conservatory, and come face to face with lions at a top-ranked zoo. Then drive 15 minutes east for a full day at Adventureland's coasters and water rides. Easy parking, friendly locals, and prices that won't sting. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Tour the golden-domed Iowa State Capitol","Meet lions and penguins at Blank Park Zoo","Ride coasters and water slides at Adventureland Park","Explore the tropical dome at the Botanical Garden","Hands-on science fun at the Science Center of Iowa"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 4+. Everything is close together and stroller-friendly; Adventureland has a big kiddie-ride section for under-48-inch riders.","lat":41.58981,"lng":-93.61538,"itinerary":[{"day":1,"title":"Capitol and Gardens","morning":{"stop":"Iowa State Capitol","description":"Start at the stunning 1880s Capitol with its 23-karat gold dome. Free guided tours (est.) take you up the grand staircase past the law library's spiral staircases \u2014 kids love the echo in the rotunda and the tiny model of the building.","cost":"Free tours (est.)","time":"9:30 AM \u2013 11:30 AM"},"afternoon":{"stop":"Greater Des Moines Botanical Garden","description":"Across the river, step into the geodesic conservatory's tropical dome \u2014 orchids, palms, and a koi pond in the middle of Iowa. The outdoor gardens are lovely in summer, and the caf\u00e9 makes an easy lunch.","cost":"$12/adult, $7/child (est.)","time":"12:30 PM \u2013 3:00 PM"},"evening":{"stop":"East Village dinner","description":"Wander the East Village's shops and murals, then grab dinner \u2014 the neighborhood is full of family-friendly pizza, taco, and burger spots within walking distance of the Capitol.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo and Science","morning":{"stop":"Blank Park Zoo","description":"Iowa's only accredited zoo is compact and well-designed: sea lions, giraffes, red pandas, and an Australian walkabout with wallabies. Arrive at opening to catch the animals at their most active.","cost":"$19.95/adult, $11.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Science Center of Iowa","description":"Six interactive learning zones plus a planetarium keep kids experimenting for hours \u2014 build, splash, and climb through physics. The live science demos are a highlight; check the daily schedule at the door.","cost":"$17/adult, $12/child (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner downtown","description":"The Court Avenue district has plenty of casual family restaurants. After dinner, walk the riverfront trail along the Des Moines River as the skyline lights up.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Adventureland Day","morning":{"stop":"Adventureland Park","description":"Drive 15 minutes to Altoona for Iowa's big theme park. Hit the coasters early \u2014 The Monster and the Underground are the headliners \u2014 while the little ones enjoy the huge kiddie areas and the classic carousel.","cost":"$49.99/person day pass (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Adventure Bay water park","description":"Cool off at the park's included water park: wave pool, lazy river, and slides for all thrill levels. Rent a locker, reapply sunscreen, and let the kids run the afternoon.","cost":"Included with admission (est.)","time":"1:30 PM \u2013 5:00 PM"},"evening":{"stop":"Drive back and farewell dinner","description":"Head back to Des Moines for a farewell dinner \u2014 you've earned the famous pork tenderloin sandwich somewhere along the way. An easy evening after a full park day.","cost":"$50\u2013$70 dinner for four (est.)","time":"6:00 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Iowa State Capitol","description":"One of America's most beautiful capitol buildings, crowned with a 23-karat gold dome. Free guided tours wind past marble staircases, historic battle flags, and the stunning law library \u2014 a surprisingly kid-friendly hour.","officialUrl":"https://www.legis.iowa.gov","price":"Free tours (est.)","photos":["assets/midwest-west/des-moines-ia-city/attr1-1.jpg","assets/midwest-west/des-moines-ia-city/attr1-2.jpg","assets/midwest-west/des-moines-ia-city/attr1-3.jpg","assets/midwest-west/des-moines-ia-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Iowa%20State%20Capitol%20Des%20Moines%20IA"},{"name":"Greater Des Moines Botanical Garden","description":"A seven-acre garden on the Des Moines River anchored by a geodesic conservatory filled with tropical plants, orchids, and waterfalls. The outdoor gardens bloom spring through fall, and the caf\u00e9 overlooks it all.","officialUrl":"https://www.dmbotanicalgarden.com","price":"$12/adult, $7/child (est.)","photos":["assets/midwest-west/des-moines-ia-city/attr2-1.jpg","assets/midwest-west/des-moines-ia-city/attr2-2.jpg","assets/midwest-west/des-moines-ia-city/attr2-3.jpg","assets/midwest-west/des-moines-ia-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Greater%20Des%20Moines%20Botanical%20Garden%20Des%20Moines%20IA"},{"name":"Blank Park Zoo","description":"Iowa's only accredited zoo, home to sea lions, giraffes, rhinos, and red pandas across themed habitats. Compact enough to see in half a day, with feedings and keeper talks that kids love.","officialUrl":"https://www.blankparkzoo.com","price":"$19.95/adult, $11.95/child (est.)","photos":["assets/midwest-west/des-moines-ia-city/attr3-1.jpg","assets/midwest-west/des-moines-ia-city/attr3-2.jpg","assets/midwest-west/des-moines-ia-city/attr3-3.jpg","assets/midwest-west/des-moines-ia-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Blank%20Park%20Zoo%20Des%20Moines%20IA"},{"name":"Science Center of Iowa","description":"A hands-on science museum with six interactive zones, live demos, and a planetarium. Kids can build rockets, play with water physics, and climb through a giant heart \u2014 learning disguised as play.","officialUrl":"https://www.sciowa.org","price":"$17/adult, $12/child (est.)","photos":["assets/midwest-west/des-moines-ia-city/attr4-1.jpg","assets/midwest-west/des-moines-ia-city/attr4-2.jpg","assets/midwest-west/des-moines-ia-city/attr4-3.jpg","assets/midwest-west/des-moines-ia-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Science%20Center%20of%20Iowa%20Des%20Moines%20IA"},{"name":"Adventureland Park","description":"Iowa's largest theme park: 100+ rides including serious coasters, a full water park, and big kiddie areas. An easy full day 15 minutes from downtown Des Moines \u2014 arrive at opening and stay through the evening show.","officialUrl":"https://www.adventurelandresort.com","price":"$49.99/person day pass (est.)","photos":["assets/midwest-west/des-moines-ia-city/attr5-1.jpg","assets/midwest-west/des-moines-ia-city/attr5-2.jpg","assets/midwest-west/des-moines-ia-city/attr5-3.jpg","assets/midwest-west/des-moines-ia-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Adventureland%20Park%20Altoona%20IA"}],"restaurants":[{"name":"Zombie Burger","detail":"A wildly themed burger joint downtown \u2014 zombie d\u00e9cor, creative burgers, and boozy shakes the kids will talk about for weeks.","price":"$$"},{"name":"Fong's Pizza","detail":"Tiki-bar-meets-pizza in the Court Avenue district; the crab rangoon pizza is legendary and the atmosphere is pure fun.","price":"$$"},{"name":"Machine Shed","detail":"A farm-themed Iowa classic serving hearty comfort food \u2014 pot roast, fried chicken, and cinnamon rolls the size of your head.","price":"$$"}],"rainyDay":["Science Center of Iowa \u2014 hands-on exhibits and a planetarium downtown","Greater Des Moines Botanical Garden \u2014 the tropical conservatory is warm year-round","Iowa State Capitol \u2014 free guided tours of the golden-domed landmark"],"driveNotes":"Des Moines sits at the crossroads of I-35 and I-80, an easy drive from anywhere in the Midwest. Downtown parking is cheap and plentiful; most attractions are 10 minutes apart. Adventureland is 15 minutes east in Altoona \u2014 buy tickets online to skip the gate line in summer.","related":["twin-cities-mn-city","iowa-city-ia-college","kansas-city-mo-city"],"imageAsset":"assets/midwest-west/des-moines-ia-city/hero.jpg"},{"id":"dubuque-ia-river","title":"Dubuque, IA: Three-Day River Adventure","destination":"Dubuque, IA","state":"IA","stateName":"Iowa","region":"Eastern Iowa","days":3,"tripType":"river adventure","interests":["family","museums","outdoors","scenic","historical-sites"],"budget":850,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Bluffs, a river museum, and the world's shortest, steepest railway \u2014 Dubuque is Iowa's prettiest surprise.","overview":"Where Iowa, Illinois, and Wisconsin meet, the Mississippi squeezes between tall limestone bluffs \u2014 and Dubuque sits right in the middle of the view. Ride a 140-year-old elevator car up the bluff, explore a Smithsonian-affiliated river museum with real steamboats, and hike the bluffs where eagles soar. It's a relaxed, scenic trip that feels like a discovery. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride the historic Fenelon Place Elevator up the bluff","Explore steamboats and aquariums at the River Museum","Hike the bluffs at Mines of Spain","Catch sunset from Eagle Point Park's overlooks","Wander 52 acres of gardens at the Dubuque Arboretum"],"bestSeason":"May\u2013October","familyFriendly":"Best for ages 5+. Bluff trails have steep drop-offs \u2014 keep little ones close at overlooks; the elevator ride delights all ages.","lat":42.49919,"lng":-90.66304,"itinerary":[{"day":1,"title":"Riverfront Day","morning":{"stop":"National Mississippi River Museum & Aquarium","description":"Start at this Smithsonian-affiliated museum on the riverfront. Tour the historic steamboat William M. Black, watch otters and alligators in the aquariums, and let the kids pilot a barge simulator. Plan on three hours minimum.","cost":"$19.95/adult, $12.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Fenelon Place Elevator","description":"Ride the world's shortest, steepest scenic railway \u2014 a tiny 1890s elevator car that climbs 189 feet up the bluff in seconds. The view from the top stretches across three states; the ride back down is half the fun.","cost":"$4/adult, $2/child round trip (est.)","time":"1:30 PM \u2013 3:00 PM"},"evening":{"stop":"Dinner on the riverfront","description":"The Port of Dubuque area has family-friendly restaurants with river views. After dinner, walk the Mississippi Riverwalk as the sun sets behind the Julien Dubuque Bridge.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Bluffs and Parks","morning":{"stop":"Mines of Spain Recreation Area","description":"Hike the bluffs Julien Dubuque mined in the 1780s. The Horseshoe Bluff trail is a moderate loop with eagle-eye views of the Mississippi; the nature center has kid-friendly exhibits about the area's lead-mining past.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Eagle Point Park","description":"This 164-acre clifftop park has some of the best views on the upper Mississippi \u2014 stone overlooks, a wading pool in summer, and huge old trees. Pack a picnic and let the kids run the playgrounds.","cost":"$2/vehicle entry (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Downtown dinner","description":"Dubuque's downtown has a fun, walkable main street with family restaurants and an old-time candy shop. Save room for dessert \u2014 the ice cream parlors here are excellent.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Gardens and History","morning":{"stop":"Dubuque Arboretum & Botanical Gardens","description":"Wander 52 acres of free gardens \u2014 the English knot garden, the rose garden, and the whimsical children's garden with its tiny houses. It's peaceful, pretty, and a great slow morning.","cost":"Free (est.)","time":"9:30 AM \u2013 11:30 AM"},"afternoon":{"stop":"Mathias Ham Historic Site","description":"Tour the 1856 mansion of one of Dubuque's founding fathers, with costumed guides and beautiful river views from the bluff-top lawn. Kids enjoy the hands-on history activities in summer.","cost":"$10/adult, $5/child (est.)","time":"12:30 PM \u2013 2:30 PM"},"evening":{"stop":"Farewell along the river","description":"One last stroll on the Riverwalk and dinner at a riverfront spot. If you're here on a summer weekend, check for the free concerts in the park series.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"National Mississippi River Museum & Aquarium","description":"A Smithsonian-affiliated museum on the Dubuque riverfront covering 10,000 years of Mississippi River life. Tour a real steamboat, meet alligators and otters, and try the barge simulator \u2014 a full half-day for families.","officialUrl":"https://www.rivermuseum.org","price":"$19.95/adult, $12.95/child (est.)","photos":["assets/midwest-west/dubuque-ia-river/attr1-1.jpg","assets/midwest-west/dubuque-ia-river/attr1-2.jpg","assets/midwest-west/dubuque-ia-river/attr1-3.jpg","assets/midwest-west/dubuque-ia-river/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=National%20Mississippi%20River%20Museum%20%26%20Aquarium%20Dubuque%20IA"},{"name":"Fenelon Place Elevator","description":"The world's shortest, steepest scenic railway: a tiny cable car climbing 189 feet up the bluff since 1882. The three-state view from the top is spectacular, and the ride itself is a thrill kids never forget.","officialUrl":"https://www.fenelonplaceelevator.com","price":"$4/adult, $2/child round trip (est.)","photos":["assets/midwest-west/dubuque-ia-river/attr2-1.jpg","assets/midwest-west/dubuque-ia-river/attr2-2.jpg","assets/midwest-west/dubuque-ia-river/attr2-3.jpg","assets/midwest-west/dubuque-ia-river/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fenelon%20Place%20Elevator%20Dubuque%20IA"},{"name":"Mines of Spain Recreation Area","description":"1,400 acres of bluffs, prairie, and river views where Julien Dubuque mined lead in the 1780s. Trails range from easy nature walks to the dramatic Horseshoe Bluff overlook, with a nature center for rainy moments.","officialUrl":"https://www.iowadnr.gov","price":"Free (est.)","photos":["assets/midwest-west/dubuque-ia-river/attr3-1.jpg","assets/midwest-west/dubuque-ia-river/attr3-2.jpg","assets/midwest-west/dubuque-ia-river/attr3-3.jpg","assets/midwest-west/dubuque-ia-river/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mines%20of%20Spain%20Recreation%20Area%20Dubuque%20IA"},{"name":"Eagle Point Park","description":"A 164-acre park perched on the bluffs with stone overlooks gazing down the Mississippi. Wading pool, playgrounds, and picnic areas make it Dubuque's favorite sunset spot \u2014 bring a camera.","officialUrl":"https://www.cityofdubuque.org","price":"$2/vehicle entry (est.)","photos":["assets/midwest-west/dubuque-ia-river/attr4-1.jpg","assets/midwest-west/dubuque-ia-river/attr4-2.jpg","assets/midwest-west/dubuque-ia-river/attr4-3.jpg","assets/midwest-west/dubuque-ia-river/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Eagle%20Point%20Park%20Dubuque%20IA"},{"name":"Dubuque Arboretum & Botanical Gardens","description":"Fifty-two acres of free gardens maintained entirely by volunteers: formal rose gardens, a Japanese garden, and a children's garden with storybook houses. A calm, colorful morning for all ages.","officialUrl":"https://dubuquearboretum.net","price":"Free (est.)","photos":["assets/midwest-west/dubuque-ia-river/attr5-1.jpg","assets/midwest-west/dubuque-ia-river/attr5-2.jpg","assets/midwest-west/dubuque-ia-river/attr5-3.jpg","assets/midwest-west/dubuque-ia-river/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dubuque%20Arboretum%20%26%20Botanical%20Gardens%20Dubuque%20IA"}],"restaurants":[{"name":"Breitbach's Country Dining","detail":"A beloved Iowa institution in nearby Balltown serving family-style comfort food \u2014 fried chicken, roast beef, and pie \u2014 since 1852.","price":"$$"},{"name":"Caroline's Restaurant","detail":"An elegant but family-welcoming spot in the Hotel Julien serving Midwestern classics with river-town charm.","price":"$$"},{"name":"L. May Eatery","detail":"A cozy downtown caf\u00e9 with creative sandwiches, salads, and excellent coffee \u2014 perfect for lunch between sights.","price":"$"}],"rainyDay":["National Mississippi River Museum & Aquarium \u2014 steamboats, aquariums, and simulators indoors","Dubuque Museum of Art \u2014 a compact downtown art museum","Grand River Center area shops and the riverfront's indoor attractions"],"driveNotes":"Dubuque is 3 hours from Des Moines or Chicago via Highway 20. The bluffs mean winding roads \u2014 the drive up to Eagle Point Park and Fenelon Place is steep but well-maintained. Downtown parking is easy; the riverfront has large free lots near the museum.","related":["des-moines-ia-city","iowa-city-ia-college","duluth-mn-northshore"],"imageAsset":"assets/midwest-west/dubuque-ia-river/hero.jpg"},{"id":"okoboji-ia-lakes","title":"Okoboji, IA: Three-Day Lake Getaway","destination":"Okoboji, IA","state":"IA","stateName":"Iowa","region":"Iowa Great Lakes","days":3,"tripType":"lake getaway","interests":["family","outdoors","amusement-parks","beaches"],"budget":850,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Iowa's lake-culture capital: an old-time amusement park, sandy beaches, and sunsets that stop traffic.","overview":"The Iowa Great Lakes have been the Midwest's summer playground for over a century, and Okoboji is the heart of it. Ride a 1920s wooden roller coaster at Arnolds Park, swim at sandy state-park beaches, and end every day watching the sun melt into West Lake Okoboji. It's nostalgic, easy, and built for families who like their vacations unhurried. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride the historic wooden coaster at Arnolds Park Amusement Park","Swim at the sandy beaches of Gull Point State Park","Boat or parasail on West Lake Okoboji","Explore hands-on nature exhibits at the Dickinson County Nature Center","Catch a sunset from the Barefoot Bar's tiki beach"],"bestSeason":"June\u2013September","familyFriendly":"Best for ages 3+. Beaches are shallow and sandy; Arnolds Park rides skew young with a classic kiddie area.","lat":43.36124,"lng":-95.14058,"itinerary":[{"day":1,"title":"Arnolds Park Day","morning":{"stop":"Arnolds Park Amusement Park","description":"Iowa's classic lakeside amusement park has been delighting families since 1889. Ride the 1920s Legend wooden coaster, spin on the vintage carousel, and let little ones loose in the kiddie ride area \u2014 all steps from the lake.","cost":"$35/person ride wristband (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Arnolds Park lakefront","description":"Walk the park's lakefront promenade, ride the Queen II excursion boat for a narrated lake tour, and grab the famous Nutty Bar ice cream treat. The maritime museum here is a nice cool-down stop.","cost":"Queen II $20/adult, $10/child (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner and sunset","description":"Have dinner at a lakeside spot in Arnolds Park, then stay for the sunset \u2014 the west-facing shore puts on a show. Summer weekends often bring free concerts in the park's Preservation Plaza.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Beach and Nature Day","morning":{"stop":"Gull Point State Park","description":"Claim a spot at one of the Iowa Great Lakes' best swimming beaches. The sand is soft, the water warms up by July, and the park's trails make a nice mid-morning leg-stretcher.","cost":"Free with Iowa parks; non-resident vehicle permit $9/day (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Dickinson County Nature Center","description":"This excellent (and free) nature center has live animals, a butterfly house in summer, and hands-on exhibits about the lakes' ecology. The trails outside wind through prairie and wetlands \u2014 great for spotting herons.","cost":"Free (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"The Barefoot Bar","description":"Okoboji's famous tiki bar sits right on East Lake with palm trees, live music, and a beach for the kids. It's touristy in the best way \u2014 arrive before sunset for a table with a view.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Boats and Rock 'n' Roll","morning":{"stop":"Morning on West Lake Okoboji","description":"Rent a pontoon or a jet ski for a half day and explore the chain of lakes. Swim off the boat in a quiet bay, or just cruise past the legendary lake cottages \u2014 some have been in families for generations.","cost":"$200\u2013$300 half-day pontoon (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Iowa Rock 'n Roll Music Association Hall of Fame & Museum","description":"In the Roof Garden Ballroom building at Arnolds Park, this museum celebrates Iowa's rock history \u2014 including the Surf Ballroom's Buddy Holly connection. Memorabilia, listening stations, and lots of photo ops.","cost":"$10/adult, $5/child (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Farewell dinner in Okoboji","description":"One last lakeside dinner as the boats come in. If it's a Saturday in summer, the Arnolds Park amusement park stays open late \u2014 a final coaster ride is the perfect goodbye.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Arnolds Park Amusement Park","description":"A lakeside amusement park operating since 1889, starring the 1920s Legend wooden roller coaster and a beautifully restored vintage carousel. The lakefront setting, free concerts, and classic rides make it pure Americana.","officialUrl":"https://www.arnoldspark.com","price":"$35/person ride wristband (est.)","photos":["assets/midwest-west/okoboji-ia-lakes/attr1-1.jpg","assets/midwest-west/okoboji-ia-lakes/attr1-2.jpg","assets/midwest-west/okoboji-ia-lakes/attr1-3.jpg","assets/midwest-west/okoboji-ia-lakes/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Arnolds%20Park%20Amusement%20Park%20Arnolds%20Park%20IA"},{"name":"West Lake Okoboji","description":"One of Iowa's few natural blue-water lakes, ringed with beaches, marinas, and a century of summer tradition. Boat, swim, parasail, or just watch the sunset \u2014 the lake is the whole point of Okoboji.","officialUrl":"https://www.vacationokoboji.com","price":"Free; boat rentals from $200/half day (est.)","photos":["assets/midwest-west/okoboji-ia-lakes/attr2-1.jpg","assets/midwest-west/okoboji-ia-lakes/attr2-2.jpg","assets/midwest-west/okoboji-ia-lakes/attr2-3.jpg","assets/midwest-west/okoboji-ia-lakes/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=West%20Lake%20Okoboji%20Okoboji%20IA"},{"name":"Dickinson County Nature Center","description":"A first-rate free nature center with live native animals, a pollinator garden, and trails through prairie and wetland. The summer butterfly house and the kids' discovery zone make it a family favorite.","officialUrl":"https://www.dickinsoncountynaturecenter.com","price":"Free (est.)","photos":["assets/midwest-west/okoboji-ia-lakes/attr3-1.jpg","assets/midwest-west/okoboji-ia-lakes/attr3-2.jpg","assets/midwest-west/okoboji-ia-lakes/attr3-3.jpg","assets/midwest-west/okoboji-ia-lakes/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dickinson%20County%20Nature%20Center%20Okoboji%20IA"},{"name":"Iowa Rock 'n Roll Hall of Fame & Museum","description":"Housed in the historic Roof Garden Ballroom, this museum honors Iowa's rock 'n' roll heritage \u2014 from the Surf Ballroom's fateful 1959 Winter Dance Party to local legends. Interactive exhibits and memorabilia galore.","officialUrl":"https://iowarocknroll.com","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/okoboji-ia-lakes/attr4-1.jpg","assets/midwest-west/okoboji-ia-lakes/attr4-2.jpg","assets/midwest-west/okoboji-ia-lakes/attr4-3.jpg","assets/midwest-west/okoboji-ia-lakes/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Iowa%20Rock%20%27n%20Roll%20Hall%20of%20Fame%20%26%20Museum%20Arnolds%20Park%20IA"},{"name":"Gull Point State Park","description":"A 195-acre state park on West Lake Okoboji with one of the area's best swimming beaches, plus hiking trails through oak woods and a lodge-style stone shelter. A classic Iowa state-park day.","officialUrl":"https://www.iowadnr.gov","price":"Free for Iowa plates; non-resident vehicle permit $9/day (est.)","photos":["assets/midwest-west/okoboji-ia-lakes/attr5-1.jpg","assets/midwest-west/okoboji-ia-lakes/attr5-2.jpg","assets/midwest-west/okoboji-ia-lakes/attr5-3.jpg","assets/midwest-west/okoboji-ia-lakes/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Gull%20Point%20State%20Park%20Milford%20IA"}],"restaurants":[{"name":"The Barefoot Bar","detail":"Okoboji's iconic tiki bar on East Lake \u2014 palm trees, live music, a beach for kids, and surprisingly good bar food.","price":"$$"},{"name":"Tweeter's Bar & Grill","detail":"A 50-year Okoboji institution serving juicy lucys, walleye sandwiches, and famous Sunday pan-fried chicken.","price":"$$"},{"name":"Nutty Bar Stand","detail":"The legendary Arnolds Park ice cream stand \u2014 the Nutty Bar (vanilla ice cream, chocolate, and peanuts) is a rite of passage.","price":"$"}],"rainyDay":["Iowa Rock 'n Roll Hall of Fame & Museum \u2014 memorabilia and music history indoors","Dickinson County Nature Center \u2014 live animals and hands-on exhibits","Arnolds Park's indoor attractions and the maritime museum on the lakefront"],"driveNotes":"Okoboji is 3.5 hours northwest of Des Moines via Highway 20 and US-71. Summer weekends fill up \u2014 book lodging months ahead for July. The lakes area is compact; everything is within 15 minutes. Note Iowa state parks charge non-resident vehicles a daily permit (est.).","related":["brainerd-mn-lakes","lake-ozarks-mo-lake","des-moines-ia-city"],"imageAsset":"assets/midwest-west/okoboji-ia-lakes/hero.jpg"},{"id":"iowa-city-ia-college","title":"Iowa City, IA: Two-Day College Town Getaway","destination":"Iowa City, IA","state":"IA","stateName":"Iowa","region":"Eastern Iowa","days":2,"tripType":"college town getaway","interests":["family","museums","food","historical-sites"],"budget":550,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"A walkable college town with a dinosaur museum, fossil gorge, and the old stone capitol.","overview":"Iowa City is the kind of college town families love: compact, walkable, and full of free or cheap attractions tied to the University of Iowa. Hunt for 375-million-year-old fossils in a gorge, come face to face with a giant ground sloth at the natural history museum, and climb the steps of the Old Capitol. Two easy days, zero stress. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Meet a giant sloth at the UI Museum of Natural History","Hunt real fossils at the Devonian Fossil Gorge","Tour the Old Capitol's golden dome","Play and build at the Iowa Children's Museum","Stroll the pedestrian-friendly downtown and campus"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The fossil gorge involves scrambling on rocks \u2014 bring sturdy shoes; the museums are stroller-friendly.","lat":41.65782,"lng":-91.52653,"itinerary":[{"day":1,"title":"Campus Museums Day","morning":{"stop":"University of Iowa Museum of Natural History","description":"In Macbride Hall, this 160-year-old museum is a time capsule kids adore: a giant ground sloth, mammoth skeletons, and bird halls with hundreds of specimens. The old-fashioned wooden cases are part of the charm.","cost":"Free (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Old Capitol Museum","description":"The golden-domed Old Capitol anchors the Pentacrest. Climb to the rotunda, see the historic legislative chambers, and learn how Iowa went from territory to state \u2014 the exhibits are short and visual enough for kids.","cost":"Free (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Downtown Iowa City dinner","description":"The downtown ped mall area is made for strolling \u2014 street performers in summer, bookstores, and plenty of family restaurants. Try the legendary Hamburg Inn No. 2, a presidential-campaign stop famous for its pie shakes.","cost":"$45\u2013$65 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Fossils and Play","morning":{"stop":"Devonian Fossil Gorge","description":"Drive 15 minutes to Coralville for one of Iowa's coolest free attractions: a 375-million-year-old ocean floor exposed by a 1993 flood, littered with brachiopods, corals, and crinoids. Kids can hunt (and keep looking, not taking) real fossils among the rocks.","cost":"Free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Iowa Children's Museum","description":"In Coralville's Iowa River Landing, this hands-on museum lets kids build, climb, splash, and pretend \u2014 the airplane cockpit and the grocery store are perennial favorites. A perfect high-energy afternoon.","cost":"$10/person (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Plum Grove and farewell","description":"On the way out, stop at Plum Grove, the 1840s home of Iowa's first territorial governor \u2014 the gardens are lovely at golden hour. Then a casual farewell dinner back in town.","cost":"Free grounds; dinner $45\u2013$65 for four (est.)","time":"4:30 PM \u2013 7:30 PM"}}],"attractions":[{"name":"University of Iowa Museum of Natural History","description":"Iowa's oldest museum, in historic Macbride Hall: towering mammoth and giant sloth skeletons, halls of birds and mammals, and beautifully old-fashioned exhibits. Free, fascinating, and right on the Pentacrest.","officialUrl":"https://mnh.uiowa.edu","price":"Free (est.)","photos":["assets/midwest-west/iowa-city-ia-college/attr1-1.jpg","assets/midwest-west/iowa-city-ia-college/attr1-2.jpg","assets/midwest-west/iowa-city-ia-college/attr1-3.jpg","assets/midwest-west/iowa-city-ia-college/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=University%20of%20Iowa%20Museum%20of%20Natural%20History%20Iowa%20City%20IA"},{"name":"Iowa Children's Museum","description":"A bright, hands-on children's museum in Coralville's Iowa River Landing. Build in the construction zone, shop in the pretend grocery, and climb the two-story structures \u2014 built for burning energy while learning.","officialUrl":"https://theicm.org","price":"$10/person (est.)","photos":["assets/midwest-west/iowa-city-ia-college/attr2-1.jpg","assets/midwest-west/iowa-city-ia-college/attr2-2.jpg","assets/midwest-west/iowa-city-ia-college/attr2-3.jpg","assets/midwest-west/iowa-city-ia-college/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Iowa%20Children%27s%20Museum%20Coralville%20IA"},{"name":"Devonian Fossil Gorge","description":"A 375-million-year-old seabed exposed by floodwaters, packed with visible fossils \u2014 corals, brachiopods, and cephalopods embedded in the limestone. One of the Midwest's best free outdoor science experiences.","officialUrl":"https://www.johnsoncountyiowa.gov","price":"Free (est.)","photos":["assets/midwest-west/iowa-city-ia-college/attr3-1.jpg","assets/midwest-west/iowa-city-ia-college/attr3-2.jpg","assets/midwest-west/iowa-city-ia-college/attr3-3.jpg","assets/midwest-west/iowa-city-ia-college/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Devonian%20Fossil%20Gorge%20Coralville%20IA"},{"name":"Old Capitol Museum","description":"Iowa's last territorial capitol, crowned with a golden dome on the university's Pentacrest. Tour the restored 1850s chambers, climb toward the rotunda, and trace Iowa's path to statehood through visual, kid-friendly exhibits.","officialUrl":"https://oldcapitol.uiowa.edu","price":"Free (est.)","photos":["assets/midwest-west/iowa-city-ia-college/attr4-1.jpg","assets/midwest-west/iowa-city-ia-college/attr4-2.jpg","assets/midwest-west/iowa-city-ia-college/attr4-3.jpg","assets/midwest-west/iowa-city-ia-college/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Old%20Capitol%20Museum%20Iowa%20City%20IA"},{"name":"Plum Grove Historic Home","description":"The 1844 brick home of Robert Lucas, Iowa's first territorial governor, surrounded by lovely gardens. Guided tours bring frontier Iowa to life; the grounds are free to wander and perfect for a picnic.","officialUrl":"https://www.johnsoncountyiowa.gov","price":"Free grounds; tours $5/adult (est.)","photos":["assets/midwest-west/iowa-city-ia-college/attr5-1.jpg","assets/midwest-west/iowa-city-ia-college/attr5-2.jpg","assets/midwest-west/iowa-city-ia-college/attr5-3.jpg","assets/midwest-west/iowa-city-ia-college/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Plum%20Grove%20Historic%20Home%20Iowa%20City%20IA"}],"restaurants":[{"name":"Hamburg Inn No. 2","detail":"The legendary campaign-stop diner famous for its pie shakes and presidential visits \u2014 classic burgers and breakfast all day.","price":"$"},{"name":"Bluebird Diner","detail":"A cheerful downtown diner with creative comfort food and a great kids' menu, steps from the ped mall.","price":"$$"},{"name":"Oasis Falafel","detail":"A beloved Iowa City falafel counter \u2014 fast, fresh, cheap, and perfect for a quick family lunch.","price":"$"}],"rainyDay":["University of Iowa Museum of Natural History \u2014 dinosaurs and dioramas indoors","Iowa Children's Museum \u2014 hours of hands-on play in Coralville","Old Capitol Museum \u2014 golden dome and history exhibits on the Pentacrest"],"driveNotes":"Iowa City is 2 hours east of Des Moines on I-80, and 3.5 hours west of Chicago. Downtown parking ramps are cheap; the university area is very walkable. Coralville's Iowa River Landing (children's museum, restaurants) is 10 minutes west on I-80.","related":["dubuque-ia-river","des-moines-ia-city","pella-ia-dutch"],"imageAsset":"assets/midwest-west/iowa-city-ia-college/hero.jpg"},{"id":"pella-ia-dutch","title":"Pella, IA: Two-Day Dutch Heritage Getaway","destination":"Pella, IA","state":"IA","stateName":"Iowa","region":"Central Iowa","days":2,"tripType":"heritage getaway","interests":["family","historical-sites","food","outdoors"],"budget":500,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"Windmills, Dutch letters, and tulips \u2014 a little piece of the Netherlands in the Iowa prairie.","overview":"Pella was founded by Dutch immigrants in 1847, and it wears its heritage proudly: a working 1850s-style windmill, Dutch bakeries turning out almond-filled letters, and a historical village of 20+ authentic buildings. Add Iowa's largest lake at nearby Lake Red Rock, and you have a charming, easy two-day trip that's unlike anywhere else in the Midwest. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Climb the working Vermeer Windmill, the tallest in the US","Taste fresh Dutch letters at Jaarsma Bakery","Explore 20+ historic buildings at Pella Historical Village","Swim and hike at Lake Red Rock, Iowa's largest lake","Spot the sculptures at Big Rock Park"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The windmill climb has steep stairs \u2014 toddlers may need carrying; the village and lake are stroller-friendly.","lat":41.40773,"lng":-92.91645,"itinerary":[{"day":1,"title":"Dutch Pella","morning":{"stop":"Pella Historical Village & Vermeer Windmill","description":"Start at the Historical Village: 20+ authentic Dutch buildings including a working windmill you can climb. Costumed interpreters demonstrate crafts, and kids love the wooden-shoe making and the miniature Dutch village.","cost":"$15/adult, $7/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Downtown Pella and Jaarsma Bakery","description":"Stroll the brick streets around Central Park, with its canal and working drawbridge. Stop at Jaarsma Bakery for Dutch letters and pastries \u2014 get there early in the day before the popular items sell out.","cost":"$15\u2013$25 bakery treats (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Pella","description":"Have dinner at a downtown Pella restaurant \u2014 several have Dutch-inspired menus. Afterward, walk the Molengracht canal area as the lights come on; it's especially pretty at dusk.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Lake Red Rock Day","morning":{"stop":"Lake Red Rock","description":"Drive 15 minutes to Iowa's largest lake. Hike the Volksweg Trail, visit the visitor center's exhibits about the Des Moines River, and let the kids play at the North Overlook beach area.","cost":"Free (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Scholte House Museum","description":"Back in town, tour the 1848 home of Pella's founder, Dominie Scholte. The furnished rooms and gardens tell the story of the Dutch immigration; the tour is short and engaging for kids.","cost":"$8/adult, $4/child (est.)","time":"1:30 PM \u2013 3:00 PM"},"evening":{"stop":"Big Rock Park and farewell","description":"End at Big Rock Park, where a giant glacial boulder anchors a sculpture park and playground. Let the kids climb and run while you enjoy the prairie sunset \u2014 a relaxed finale.","cost":"Free (est.)","time":"4:00 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Pella Historical Village & Vermeer Windmill","description":"Twenty-two authentic Dutch buildings \u2014 including the 124-foot Vermeer Windmill, the tallest working windmill in the United States \u2014 filled with interpreters, crafts, and Dutch artifacts. Climbing the windmill's stages is the highlight.","officialUrl":"https://www.pellahistorical.org","price":"$15/adult, $7/child (est.)","photos":["assets/midwest-west/pella-ia-dutch/attr1-1.jpg","assets/midwest-west/pella-ia-dutch/attr1-2.jpg","assets/midwest-west/pella-ia-dutch/attr1-3.jpg","assets/midwest-west/pella-ia-dutch/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pella%20Historical%20Village%20%26%20Vermeer%20Windmill%20Pella%20IA"},{"name":"Lake Red Rock","description":"Iowa's largest lake: 15,000 acres of water and 35,000 acres of public land with beaches, trails, and campgrounds. The visitor center overlooks the dam, and the Volksweg Trail is great for family biking.","officialUrl":"https://www.iowadnr.gov","price":"Free (est.)","photos":["assets/midwest-west/pella-ia-dutch/attr2-1.jpg","assets/midwest-west/pella-ia-dutch/attr2-2.jpg","assets/midwest-west/pella-ia-dutch/attr2-3.jpg","assets/midwest-west/pella-ia-dutch/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20Red%20Rock%20Pella%20IA"},{"name":"Scholte House Museum","description":"The 1848 home of Dominie Henry Scholte, who led 800 Dutch immigrants to found Pella. Furnished period rooms, beautiful gardens, and the story of the town's founding in one compact visit.","officialUrl":"https://www.pellahistorical.org","price":"$8/adult, $4/child (est.)","photos":["assets/midwest-west/pella-ia-dutch/attr3-1.jpg","assets/midwest-west/pella-ia-dutch/attr3-2.jpg","assets/midwest-west/pella-ia-dutch/attr3-3.jpg","assets/midwest-west/pella-ia-dutch/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Scholte%20House%20Museum%20Pella%20IA"},{"name":"Big Rock Park","description":"A city park built around a massive glacial boulder, with sculptures, walking paths, and a playground. It's a favorite local picnic spot and a fun, free wind-down for kids.","officialUrl":"https://www.cityofpella.com","price":"Free (est.)","photos":["assets/midwest-west/pella-ia-dutch/attr4-1.jpg","assets/midwest-west/pella-ia-dutch/attr4-2.jpg","assets/midwest-west/pella-ia-dutch/attr4-3.jpg","assets/midwest-west/pella-ia-dutch/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Big%20Rock%20Park%20Pella%20IA"},{"name":"Jaarsma Bakery","description":"The legendary Dutch bakery operating since 1898 \u2014 the almond-filled Dutch letters draw lines out the door. Watching the bakers work through the window is half the fun; the pastries are the other half.","officialUrl":"https://www.jaarsmabakery.com","price":"$3\u2013$12 treats (est.)","photos":["assets/midwest-west/pella-ia-dutch/attr5-1.jpg","assets/midwest-west/pella-ia-dutch/attr5-2.jpg","assets/midwest-west/pella-ia-dutch/attr5-3.jpg","assets/midwest-west/pella-ia-dutch/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jaarsma%20Bakery%20Pella%20IA"}],"restaurants":[{"name":"Jaarsma Bakery","detail":"The 125-year-old Dutch bakery \u2014 Dutch letters, almond pastries, and coffee; go early before the best items sell out.","price":"$"},{"name":"George's Pizza & Steakhouse","detail":"A Pella institution for thin-crust pizza and steaks in a family-friendly downtown dining room.","price":"$$"},{"name":"The Cellar Peanut Pub","detail":"A cozy basement pub downtown with great burgers and a famous peanut-barrel tradition the kids will love.","price":"$$"}],"rainyDay":["Pella Historical Village \u2014 many buildings are indoors, and the windmill tour runs rain or shine","Scholte House Museum \u2014 furnished historic interiors","Pella Community Center pool and the downtown shops along Franklin Street"],"driveNotes":"Pella is 45 minutes southeast of Des Moines on Highway 163 \u2014 an easy day trip or weekend from the capital. Everything in town is within a few blocks; Lake Red Rock is 15 minutes north. Visit during the Tulip Time festival (early May) for peak Dutch pageantry, but book lodging far ahead.","related":["iowa-city-ia-college","des-moines-ia-city","hutchinson-ks-space"],"imageAsset":"assets/midwest-west/pella-ia-dutch/hero.jpg"},{"id":"st-louis-mo-city","title":"St. Louis, MO: Four-Day City Adventure","destination":"St. Louis, MO","state":"MO","stateName":"Missouri","region":"Eastern Missouri","days":4,"tripType":"city adventure","interests":["family","museums","food","historical-sites"],"budget":1200,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days, excluding lodging upgrades.","tagline":"Ride to the top of the Arch, meet the penguins for free, and climb through a museum made of pure imagination.","overview":"St. Louis is one of America's best-value family cities: the world-famous zoo is free, the Arch is unforgettable, and the food scene \u2014 from toasted ravioli to frozen custard \u2014 keeps everyone happy. Add a one-of-a-kind museum built from salvaged city materials and a botanical garden that stuns in every season, and you have four full days without repeating yourself. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride the tram 630 feet to the top of the Gateway Arch","Explore the Saint Louis Zoo \u2014 free admission","Climb and slide through City Museum's wild playgrounds","Wander the Japanese garden at the Missouri Botanical Garden","Toasted ravioli, gooey butter cake, and Ted Drewes custard"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. City Museum's climbing structures suit adventurous kids 5+; the zoo and Arch are great for all ages.","lat":38.62775,"lng":-90.19956,"itinerary":[{"day":1,"title":"Gateway Arch Day","morning":{"stop":"Gateway Arch National Park","description":"Book the first tram ride of the day to the top of the 630-foot Arch \u2014 the tiny capsules are an adventure in themselves, and the view spans the whole city and river. Allow time for the excellent museum underneath, which tells the westward-expansion story.","cost":"Tram $15/adult, $10/child; museum free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Riverfront and lunch","description":"Walk the riverfront trail, watch the barges, and grab lunch at a nearby spot. If the kids need to move, the park's grounds are great for running around with the Arch towering overhead.","cost":"$40\u2013$60 lunch for four (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Ted Drewes Frozen Custard","description":"No St. Louis trip is complete without Ted Drewes on Chippewa. The line moves fast, the concretes are legendary, and the neon sign is a photo op. Then an easy evening \u2014 tomorrow is the zoo.","cost":"$20\u2013$30 for four (est.)","time":"6:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo and Forest Park","morning":{"stop":"Saint Louis Zoo","description":"One of the country's best zoos \u2014 and admission is free. Start at Penguin & Puffin Coast, then the primate house and the big-cat country. Arrive at opening; the free zoo draws crowds by midday.","cost":"Free admission; parking $15 (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Saint Louis Science Center","description":"Across Forest Park, the Science Center's free general admission covers hands-on exhibits, a planetarium show, and the life-science labs. The bridge over the highway between buildings is an adventure itself.","cost":"Free general admission; planetarium $8/person (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"The Hill dinner","description":"Head to The Hill, St. Louis's historic Italian neighborhood, for toasted ravioli and pasta. It's a lively, family-welcoming area \u2014 save room for gelato.","cost":"$60\u2013$80 dinner for four (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":3,"title":"City Museum Day","morning":{"stop":"City Museum","description":"Devote the whole morning to this one-of-a-kind wonderland built from salvaged architectural pieces: climb through a 10-story slide, explore caves, and scale the outdoor MonstroCity. Wear clothes that can get dirty and knee pads if you have them.","cost":"$20/person general admission (est.)","time":"10:00 AM \u2013 1:30 PM"},"afternoon":{"stop":"City Museum \u2014 rooftop and more","description":"After lunch (the museum has a decent caf\u00e9), hit the rooftop with its Ferris wheel and slides, then revisit favorite caves. Most families need 4\u20135 hours total \u2014 don't rush it.","cost":"Included with admission (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Rest and casual dinner","description":"The kids will be happily exhausted. Grab a casual dinner near your hotel \u2014 barbecue or pizza \u2014 and call it an early night.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 7:30 PM"}},{"day":4,"title":"Gardens and Farewell","morning":{"stop":"Missouri Botanical Garden","description":"End with one of the world's great botanical gardens: the Climatron geodesic dome, the serene Japanese garden, and the children's garden with its treehouse village. It's peaceful, gorgeous, and a gentle finale.","cost":"$16/adult, kids under 12 free (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Soulard and the river","description":"Grab lunch in the historic Soulard neighborhood \u2014 the farmers' market (Saturday mornings) is fantastic. One last walk along the riverfront before heading home.","cost":"$40\u2013$60 lunch for four (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Drive home","description":"Hit the road with a car full of tired, happy kids \u2014 and maybe one more Ted Drewes stop if you're heading west. St. Louis does family trips right.","cost":"Gas and snacks (est.)","time":"4:00 PM \u2013 6:00 PM"}}],"attractions":[{"name":"Gateway Arch National Park","description":"The 630-foot stainless steel Arch is America's tallest monument \u2014 ride the tiny tram capsules to the top for a view across two states. The underground museum brilliantly tells the story of westward expansion.","officialUrl":"https://www.gatewayarch.com","price":"Tram $15/adult, $10/child; museum free (est.)","photos":["assets/midwest-west/st-louis-mo-city/attr1-1.jpg","assets/midwest-west/st-louis-mo-city/attr1-2.jpg","assets/midwest-west/st-louis-mo-city/attr1-3.jpg","assets/midwest-west/st-louis-mo-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Gateway%20Arch%20National%20Park%20St.%20Louis%20MO"},{"name":"Saint Louis Zoo","description":"Consistently ranked among the world's best zoos \u2014 and free. Penguin & Puffin Coast, the primate house, and Big Cat Country anchor a full day in beautiful Forest Park.","officialUrl":"https://www.stlzoo.org","price":"Free admission; parking $15 (est.)","photos":["assets/midwest-west/st-louis-mo-city/attr2-1.jpg","assets/midwest-west/st-louis-mo-city/attr2-2.jpg","assets/midwest-west/st-louis-mo-city/attr2-3.jpg","assets/midwest-west/st-louis-mo-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Saint%20Louis%20Zoo%20St.%20Louis%20MO"},{"name":"City Museum","description":"A former shoe factory transformed into a surreal playground of salvaged staircases, slides, caves, and climbing structures \u2014 indoors and out. There's nothing else like it; kids (and adults) climb for hours.","officialUrl":"https://www.citymuseum.org","price":"$20/person (est.)","photos":["assets/midwest-west/st-louis-mo-city/attr3-1.jpg","assets/midwest-west/st-louis-mo-city/attr3-2.jpg","assets/midwest-west/st-louis-mo-city/attr3-3.jpg","assets/midwest-west/st-louis-mo-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=City%20Museum%20St.%20Louis%20MO"},{"name":"Missouri Botanical Garden","description":"Founded in 1859, one of the world's great botanical gardens: the Climatron tropical dome, a 14-acre Japanese garden, and a children's garden with treehouses and water play. Beautiful in every season.","officialUrl":"https://www.missouribotanicalgarden.org","price":"$16/adult, kids under 12 free (est.)","photos":["assets/midwest-west/st-louis-mo-city/attr4-1.jpg","assets/midwest-west/st-louis-mo-city/attr4-2.jpg","assets/midwest-west/st-louis-mo-city/attr4-3.jpg","assets/midwest-west/st-louis-mo-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Missouri%20Botanical%20Garden%20St.%20Louis%20MO"},{"name":"Saint Louis Science Center","description":"Free general admission to hands-on science exhibits, an indoor planetarium, and the GROW agriculture pavilion. The highway-spanning bridge between buildings is part of the fun.","officialUrl":"https://www.slsc.org","price":"Free general admission; planetarium $8/person (est.)","photos":["assets/midwest-west/st-louis-mo-city/attr5-1.jpg","assets/midwest-west/st-louis-mo-city/attr5-2.jpg","assets/midwest-west/st-louis-mo-city/attr5-3.jpg","assets/midwest-west/st-louis-mo-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Saint%20Louis%20Science%20Center%20St.%20Louis%20MO"}],"restaurants":[{"name":"Pappy's Smokehouse","detail":"The St. Louis barbecue legend \u2014 expect a line, worth it for the ribs and burnt ends; get there before the lunch rush.","price":"$$"},{"name":"Ted Drewes Frozen Custard","detail":"The 1929 custard stand on Chippewa; the concrete (custard blended with toppings) is a St. Louis rite of passage.","price":"$"},{"name":"Fitz's","detail":"A Delmar Loop bottling-works-turned-restaurant where kids watch root beer bottled while eating burgers and floats.","price":"$$"}],"rainyDay":["City Museum \u2014 the ultimate indoor climbing playground","Saint Louis Science Center \u2014 free exhibits and a planetarium","Missouri History Museum \u2014 engaging exhibits in Forest Park"],"driveNotes":"St. Louis sits at the junction of I-70, I-55, I-44, and I-64 \u2014 easy from anywhere. Downtown and Forest Park parking is affordable; the MetroLink light rail connects the airport to downtown and Forest Park. Book Arch tram tickets online well ahead \u2014 they sell out in summer.","related":["kansas-city-mo-city","springfield-mo-city","wichita-ks-city"],"imageAsset":"assets/midwest-west/st-louis-mo-city/hero.jpg"},{"id":"kansas-city-mo-city","title":"Kansas City, MO: Four-Day Family Adventure","destination":"Kansas City, MO","state":"MO","stateName":"Missouri","region":"Western Missouri","days":4,"tripType":"family adventure","interests":["family","museums","food","amusement-parks","historical-sites"],"budget":1300,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days, excluding lodging upgrades.","tagline":"World-class barbecue, a towering war memorial, and one of America's best zoos \u2014 KC does it all.","overview":"Kansas City earns its family-trip reputation: a moving national WWI memorial, a zoo with a brand-new aquarium, an indoor science city inside a gorgeous old train station, and barbecue worth planning a trip around. Four days lets you hit the highlights without rushing \u2014 and you'll eat very, very well. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Stand beneath the 217-foot Liberty Memorial at the WWI Museum","Explore the new aquarium at the Kansas City Zoo","Experiment all day at Science City in Union Station","Ride coasters at Worlds of Fun","Eat your way through America's barbecue capital"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The WWI Museum's upper floors are most engaging for 8+; the zoo, Science City, and Worlds of Fun suit all ages.","lat":39.10344,"lng":-94.58311,"itinerary":[{"day":1,"title":"WWI Museum and Union Station","morning":{"stop":"National WWI Museum and Memorial","description":"Walk across the glass bridge over a field of poppies into America's official WWI museum. The Liberty Memorial tower soars 217 feet; the elevator ride up rewards you with a panorama of the whole city. Older kids get the most from the exhibits.","cost":"$20/adult, $12/child; tower $6/person (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Science City at Union Station","description":"Inside the stunning 1914 Union Station, Science City packs three floors of hands-on exhibits \u2014 a test track, a maker studio, and a nature center. It's the kind of place where three hours vanish.","cost":"$18/person (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Barbecue dinner","description":"Your first KC barbecue: burnt ends, ribs, and sauce worth arguing about. Joe's Kansas City (in a gas station, famously) is the pilgrimage \u2014 go early, the line is real.","cost":"$60\u2013$80 dinner for four (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Zoo Day","morning":{"stop":"Kansas City Zoo & Aquarium","description":"One of the country's largest zoos, now with a major aquarium addition. Africa, Australia, and the new Sobela Ocean Aquarium could fill a whole day \u2014 arrive at opening and head straight for the penguins and sharks.","cost":"$26/adult, $21/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Zoo continued","description":"After lunch at the zoo, ride the tram through the Africa section, visit the polar bears, and let the kids cool off at the splash areas. The zoo is huge \u2014 pace yourselves.","cost":"Included with admission (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Country Club Plaza dinner","description":"Dine on the beautiful Country Club Plaza, KC's 1920s Spanish-style shopping district with fountains everywhere. The kids can run the plazas while you wait for a table.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Worlds of Fun","morning":{"stop":"Worlds of Fun","description":"KC's big theme park: coasters like the Mamba and Patriot, plus the Camp Snoopy kids' area for little ones. Arrive at opening and hit the headline coasters before lines build.","cost":"$49.99/person (est.)","time":"10:30 AM \u2013 1:30 PM"},"afternoon":{"stop":"Oceans of Fun","description":"The adjacent water park is included in summer \u2014 wave pool, lazy river, and slides. A perfect hot-afternoon cooldown after the coasters.","cost":"Included with admission in summer (est.)","time":"2:00 PM \u2013 5:30 PM"},"evening":{"stop":"Fritz's Railroad Restaurant","description":"End the park day at Fritz's, where your food arrives by model train. Kids are mesmerized, the burgers are solid, and it's pure KC family tradition.","cost":"$45\u2013$60 dinner for four (est.)","time":"6:30 PM \u2013 8:30 PM"}},{"day":4,"title":"Toys, Miniatures, and Farewell","morning":{"stop":"National Museum of Toys and Miniatures","description":"On the UMKC campus, this gem holds the world's largest collection of fine-scale miniatures plus antique toys. The tiny rooms \u2014 every detail perfect \u2014 fascinate kids and adults alike.","cost":"$10/adult, $5/child (est.)","time":"10:00 AM \u2013 12:00 PM"},"afternoon":{"stop":"Union Station and Crown Center","description":"Revisit Union Station's grand hall, then walk to Crown Center for the Hallmark Visitors Center and LEGOLAND Discovery Center if the kids want one more attraction. The free streetcar connects downtown sights.","cost":"LEGOLAND $25/person (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell barbecue","description":"One last barbecue dinner \u2014 try a different legendary spot than night one. Arthur Bryant's and Q39 are both worthy. Then hit the road, full and happy.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"National WWI Museum and Memorial","description":"America's official WWI museum beneath the soaring 217-foot Liberty Memorial. Walk over a field of poppies, explore trenches and tanks, and ride to the tower top for the city's best view.","officialUrl":"https://www.theworldwar.org","price":"$20/adult, $12/child; tower $6/person (est.)","photos":["assets/midwest-west/kansas-city-mo-city/attr1-1.jpg","assets/midwest-west/kansas-city-mo-city/attr1-2.jpg","assets/midwest-west/kansas-city-mo-city/attr1-3.jpg","assets/midwest-west/kansas-city-mo-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=National%20WWI%20Museum%20and%20Memorial%20Kansas%20City%20MO"},{"name":"Kansas City Zoo & Aquarium","description":"One of America's largest zoos, now featuring the Sobela Ocean Aquarium with sharks, rays, and penguins. The Africa and Australia sections, plus polar bears and big cats, fill a full day.","officialUrl":"https://www.kansascityzoo.org","price":"$26/adult, $21/child (est.)","photos":["assets/midwest-west/kansas-city-mo-city/attr2-1.jpg","assets/midwest-west/kansas-city-mo-city/attr2-2.jpg","assets/midwest-west/kansas-city-mo-city/attr2-3.jpg","assets/midwest-west/kansas-city-mo-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kansas%20City%20Zoo%20%26%20Aquarium%20Kansas%20City%20MO"},{"name":"Science City at Union Station","description":"Three floors of hands-on science inside the breathtaking 1914 Union Station: test tracks, maker labs, a nature center, and a planetarium. The building alone is worth the visit.","officialUrl":"https://www.sciencecity.com","price":"$18/person (est.)","photos":["assets/midwest-west/kansas-city-mo-city/attr3-1.jpg","assets/midwest-west/kansas-city-mo-city/attr3-2.jpg","assets/midwest-west/kansas-city-mo-city/attr3-3.jpg","assets/midwest-west/kansas-city-mo-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Science%20City%20at%20Union%20Station%20Kansas%20City%20MO"},{"name":"Worlds of Fun","description":"Kansas City's major theme park: serious coasters (Mamba, Patriot, Timber Wolf), the Camp Snoopy kids' area, and the adjacent Oceans of Fun water park in summer. A full-throttle day.","officialUrl":"https://www.worldsoffun.com","price":"$49.99/person (est.)","photos":["assets/midwest-west/kansas-city-mo-city/attr4-1.jpg","assets/midwest-west/kansas-city-mo-city/attr4-2.jpg","assets/midwest-west/kansas-city-mo-city/attr4-3.jpg","assets/midwest-west/kansas-city-mo-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Worlds%20of%20Fun%20Kansas%20City%20MO"},{"name":"National Museum of Toys and Miniatures","description":"A UMKC treasure: the world's largest collection of fine-scale miniatures alongside antique toys dating to the 1700s. The impossibly detailed miniature rooms mesmerize all ages.","officialUrl":"https://toyandminiaturemuseum.org","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/kansas-city-mo-city/attr5-1.jpg","assets/midwest-west/kansas-city-mo-city/attr5-2.jpg","assets/midwest-west/kansas-city-mo-city/attr5-3.jpg","assets/midwest-west/kansas-city-mo-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=National%20Museum%20of%20Toys%20and%20Miniatures%20Kansas%20City%20MO"}],"restaurants":[{"name":"Joe's Kansas City Bar-B-Que","detail":"The gas-station barbecue joint Anthony Bourdain loved \u2014 burnt ends and ribs worth the famous line; go at off-hours.","price":"$$"},{"name":"Fritz's Railroad Restaurant","detail":"Burgers and shakes delivered by model train \u2014 a KC family tradition the kids will never forget.","price":"$"},{"name":"Winstead's Steakburgers","detail":"The 1940s steakburger-and-shake diner with skyscraper shakes; a nostalgic family stop near the Plaza.","price":"$"}],"rainyDay":["Science City at Union Station \u2014 three floors of hands-on exhibits indoors","National WWI Museum and Memorial \u2014 the museum galleries are all indoors","National Museum of Toys and Miniatures \u2014 tiny worlds to explore for hours"],"driveNotes":"Kansas City sits at the junction of I-70, I-35, and I-29. The free KC Streetcar connects downtown, the Power & Light District, and Union Station/Crown Center. Worlds of Fun is 15 minutes north of downtown; the zoo is 15 minutes southeast. Barbecue lines are shortest at 11 AM or after 8 PM.","related":["st-louis-mo-city","wichita-ks-city","branson-mo-family"],"imageAsset":"assets/midwest-west/kansas-city-mo-city/hero.jpg"},{"id":"branson-mo-family","title":"Branson, MO: Four-Day Family Vacation","destination":"Branson, MO","state":"MO","stateName":"Missouri","region":"Ozarks","days":4,"tripType":"family vacation","interests":["family","amusement-parks","outdoors","scenic"],"budget":1500,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days, excluding lodging upgrades.","tagline":"The Ozarks' family capital: an 1800s theme park, a gorgeous lake, and shows galore.","overview":"Branson has been entertaining families for generations, and it keeps getting better. Silver Dollar City \u2014 an 1880s Ozark mountain town that's also a world-class theme park \u2014 anchors the trip, while Table Rock Lake offers swimming, boating, and jaw-dropping scenery. Add a fish hatchery, a Titanic museum, and Branson's famous live shows, and four days fly by. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride world-class coasters at Silver Dollar City's 1880s Ozark town","Swim and boat on Table Rock Lake","Walk the grand staircase at the Titanic Museum","Feed the trout at Shepherd of the Hills Fish Hatchery","Stroll the Branson Landing boardwalk at sunset"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. Silver Dollar City has huge kiddie areas; the Titanic Museum's audio tour engages ages 8+ best.","lat":36.64158,"lng":-93.21781,"itinerary":[{"day":1,"title":"Silver Dollar City Day One","morning":{"stop":"Silver Dollar City","description":"Arrive at opening for this 1880s-themed park in the Ozark hills. Ride the headline coasters (Outlaw Run, Time Traveler) before lines build, then explore the craftsmen's shops \u2014 glassblowing, blacksmithing, candy-making \u2014 that make SDC unique.","cost":"$89/adult, $79/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Silver Dollar City continued","description":"After lunch in the park, hit the water rides (you will get soaked), the Marvel Cave tour \u2014 a stunning cave discovered in the 1800s \u2014 and the kiddie areas. Catch one of the park's shows to rest your feet.","cost":"Included with admission (est.)","time":"1:30 PM \u2013 6:00 PM"},"evening":{"stop":"Dinner on the Strip","description":"Head back to town for dinner \u2014 Branson's famous 76 Strip is lined with family restaurants. An early night; you'll want fresh legs for day two.","cost":"$60\u2013$80 dinner for four (est.)","time":"6:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Table Rock Lake Day","morning":{"stop":"Table Rock Lake","description":"Rent a pontoon or book a morning cruise on this stunningly clear Ozark lake. Swim in a quiet cove, try a little fishing, or just cruise past the limestone bluffs \u2014 the water here is some of the clearest in the Midwest.","cost":"$200\u2013$300 half-day pontoon (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Shepherd of the Hills Fish Hatchery","description":"Below Table Rock Dam, this free hatchery raises a million trout a year. Kids love feeding the fish (bring quarters for feed), touring the exhibits, and walking the trails along Lake Taneycomo.","cost":"Free (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Branson Landing","description":"Stroll the lakefront boardwalk at Branson Landing \u2014 shops, restaurants, and the famous fire-and-water fountain show every evening. Have dinner with a view of Lake Taneycomo.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:30 PM \u2013 9:00 PM"}},{"day":3,"title":"Titanic and Shows","morning":{"stop":"Titanic Museum Attraction","description":"Board a half-scale replica of the ship and receive a real passenger's boarding pass. Touch an iceberg, walk the grand staircase, and follow your passenger's story \u2014 it's immersive and moving, and kids stay engaged throughout.","cost":"$36/adult, $16/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Branson's scenic railway or downtown","description":"Take it easy: ride the Branson Scenic Railway through the Ozarks, or explore the historic downtown shops. A low-key afternoon recharges everyone for the evening show.","cost":"$30/adult, $18/child railway (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"A Branson live show","description":"Branson's famous for its shows \u2014 pick a family-friendly music or magic show on the Strip. The Presleys' and Dolly Parton's Stampede are long-running favorites for families.","cost":"$50\u2013$70/person show tickets (est.)","time":"7:00 PM \u2013 9:30 PM"}},{"day":4,"title":"Silver Dollar City Day Two","morning":{"stop":"Silver Dollar City \u2014 round two","description":"Use the second day of a two-day pass to hit everything you missed: more coasters, the craftsmen, and the shows. Two days lets you actually enjoy SDC instead of sprinting.","cost":"Two-day pass $99/adult, $89/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"White Water or the lake","description":"Cool off at Silver Dollar City's White Water park (separate ticket) or head back to Table Rock Lake for a final swim. Either way, it's a wet, happy afternoon.","cost":"$50/person White Water (est.)","time":"1:30 PM \u2013 5:00 PM"},"evening":{"stop":"Farewell dinner","description":"One last Ozark dinner \u2014 try the famous Billy Gail's for a massive breakfast-for-dinner, or classic barbecue. The drive home can wait until morning.","cost":"$55\u2013$75 dinner for four (est.)","time":"6:00 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Silver Dollar City","description":"An 1880s Ozark mountain town that's also one of America's best theme parks: world-class coasters, working craftsmen, the stunning Marvel Cave, and live shows. Plan two days \u2014 one isn't enough.","officialUrl":"https://www.silverdollarcity.com","price":"$89/adult, $79/child; two-day passes available (est.)","photos":["assets/midwest-west/branson-mo-family/attr1-1.jpg","assets/midwest-west/branson-mo-family/attr1-2.jpg","assets/midwest-west/branson-mo-family/attr1-3.jpg","assets/midwest-west/branson-mo-family/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Silver%20Dollar%20City%20Branson%20MO"},{"name":"Table Rock Lake","description":"43,000 acres of famously clear Ozark water ringed by limestone bluffs. Swim, boat, fish, or cruise \u2014 the lake's coves and marinas make it the region's natural playground.","officialUrl":"https://www.swl.usace.army.mil","price":"Free; boat rentals from $200/half day (est.)","photos":["assets/midwest-west/branson-mo-family/attr2-1.jpg","assets/midwest-west/branson-mo-family/attr2-2.jpg","assets/midwest-west/branson-mo-family/attr2-3.jpg","assets/midwest-west/branson-mo-family/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Table%20Rock%20Lake%20Branson%20MO"},{"name":"Titanic Museum Attraction","description":"A half-scale replica of the Titanic housing 400+ artifacts. Get a real passenger's boarding pass, touch an iceberg, climb the grand staircase, and discover your passenger's fate \u2014 immersive for all ages.","officialUrl":"https://www.titanicbranson.com","price":"$36/adult, $16/child (est.)","photos":["assets/midwest-west/branson-mo-family/attr3-1.jpg","assets/midwest-west/branson-mo-family/attr3-2.jpg","assets/midwest-west/branson-mo-family/attr3-3.jpg","assets/midwest-west/branson-mo-family/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Titanic%20Museum%20Attraction%20Branson%20MO"},{"name":"Shepherd of the Hills Fish Hatchery","description":"Missouri's largest trout hatchery, raising over a million fish a year below Table Rock Dam. Feed the trout, explore the free exhibits, and walk the trails along cold, clear Lake Taneycomo.","officialUrl":"https://www.mdc.mo.gov","price":"Free (est.)","photos":["assets/midwest-west/branson-mo-family/attr4-1.jpg","assets/midwest-west/branson-mo-family/attr4-2.jpg","assets/midwest-west/branson-mo-family/attr4-3.jpg","assets/midwest-west/branson-mo-family/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Shepherd%20of%20the%20Hills%20Fish%20Hatchery%20Branson%20MO"},{"name":"Branson Landing","description":"A lively lakefront district on Lake Taneycomo with shops, restaurants, and the famous fire-and-water fountain show. The boardwalk at sunset is Branson's best free evening.","officialUrl":"https://www.bransonlanding.com","price":"Free (est.)","photos":["assets/midwest-west/branson-mo-family/attr5-1.jpg","assets/midwest-west/branson-mo-family/attr5-2.jpg","assets/midwest-west/branson-mo-family/attr5-3.jpg","assets/midwest-west/branson-mo-family/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Branson%20Landing%20Branson%20MO"}],"restaurants":[{"name":"Billy Gail's Cafe","detail":"The legendary Ozark breakfast spot \u2014 pancakes bigger than the plate; arrive early, the wait is part of the experience.","price":"$$"},{"name":"Danna's BBQ & Burger Shop","detail":"A Branson local favorite for smoked barbecue and big burgers in a fun, casual setting.","price":"$$"},{"name":"Mel's Hard Luck Diner","detail":"A 1950s diner where the servers sing \u2014 burgers, shakes, and a show with dinner.","price":"$$"}],"rainyDay":["Titanic Museum Attraction \u2014 an immersive indoor ship experience","Branson's live shows \u2014 dozens of family-friendly theaters on the Strip","Shepherd of the Hills Fish Hatchery \u2014 covered exhibits plus trails for breaks in the rain"],"driveNotes":"Branson is in the Ozark hills of southwest Missouri \u2014 about 3.5 hours from Kansas City or St. Louis, 1 hour from Springfield. The 76 Strip gets very congested in summer; use the alternate routes (the tourism office maps them). Book Silver Dollar City tickets and show tickets online ahead.","related":["springfield-mo-city","lake-ozarks-mo-lake","kansas-city-mo-city"],"imageAsset":"assets/midwest-west/branson-mo-family/hero.jpg"},{"id":"springfield-mo-city","title":"Springfield, MO: Three-Day Ozarks Adventure","destination":"Springfield, MO","state":"MO","stateName":"Missouri","region":"Ozarks","days":3,"tripType":"ozarks adventure","interests":["family","museums","outdoors","nature"],"budget":900,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"The birthplace of Route 66: a world-class aquarium, a ride-through cave, and Ozark charm.","overview":"Springfield calls itself the Queen City of the Ozarks, and it backs it up with some of Missouri's best family attractions. The Wonders of Wildlife museum-aquarium is genuinely world-class, Fantastic Caverns is the only ride-through cave in America, and Route 66 history runs through downtown. It's affordable, friendly, and easy \u2014 a perfect long weekend. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk through the stunning Wonders of Wildlife aquarium","Ride through Fantastic Caverns in a Jeep-drawn tram","Meet giraffes and elephants at Dickerson Park Zoo","Cruise classic cars at the Route 66 Car Museum","Eat a throwed roll at Lambert's Cafe"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The cave tram suits all ages; Wonders of Wildlife's size means planning rest breaks for little legs.","lat":37.20897,"lng":-93.2916,"itinerary":[{"day":1,"title":"Wonders of Wildlife","morning":{"stop":"Wonders of Wildlife National Museum & Aquarium","description":"Give this one the whole morning \u2014 it's huge. The aquarium's 1.5-million-gallon tanks, shark tunnel, and penguin cove are spectacular; the wildlife galleries' dioramas are museum-quality. Arrive at opening to beat the crowds.","cost":"$39.95/adult, $24.95/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Wonders of Wildlife continued","description":"After lunch at the on-site restaurant, explore the wildlife museum half: record-book animals in lifelike habitats, plus the interactive conservation exhibits. Most families need 4\u20135 hours total.","cost":"Included with admission (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner and downtown","description":"Head downtown for dinner \u2014 the area around Park Central Square has family-friendly options. Walk off dinner with a stroll past the Route 66 murals.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Caves and Zoo","morning":{"stop":"Fantastic Caverns","description":"America's only ride-through cave: board a Jeep-drawn tram and glide past stalactites, flowstone, and underground rivers. The 55-minute tour is gentle, narrated, and perfect for all ages \u2014 no walking required.","cost":"$32/adult, $19/child (est.)","time":"9:30 AM \u2013 11:30 AM"},"afternoon":{"stop":"Dickerson Park Zoo","description":"A well-kept mid-size zoo with elephants, giraffes, cheetahs, and a great reptile house. It's compact enough to see in a few hours, and the giraffe feeding deck is a highlight.","cost":"$19/adult, $14/child (est.)","time":"1:00 PM \u2013 4:30 PM"},"evening":{"stop":"Lambert's Cafe","description":"Drive 15 minutes to Ozark for Lambert's \u2014 home of the throwed rolls, tossed across the room to your table. The portions are enormous, the wait is part of the fun, and kids love the chaos.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Route 66 and Discovery","morning":{"stop":"Route 66 Car Museum","description":"Springfield is the birthplace of Route 66, and this museum celebrates it with dozens of classic cars \u2014 vintage Corvettes, movie cars, and neon signs. Car-loving kids will be in heaven; it's a quick, fun hour.","cost":"$15/adult, $7/child (est.)","time":"10:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"Discovery Center of Springfield","description":"A hands-on children's science museum with a two-story climbing structure, dinosaur dig pit, and water play area. Perfect for burning off energy on the last day.","cost":"$14/person (est.)","time":"12:30 PM \u2013 3:30 PM"},"evening":{"stop":"Farewell on Commercial Street","description":"End on historic Commercial Street \u2014 Springfield's original downtown \u2014 with dinner at a family spot and a walk past the vintage storefronts. An easy, nostalgic goodbye.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Wonders of Wildlife National Museum & Aquarium","description":"Johnny Morris's 350,000-square-foot tribute to the outdoors: a 1.5-million-gallon aquarium with sharks and penguins plus vast wildlife dioramas. Voted America's best aquarium \u2014 it's the reason many families visit Springfield.","officialUrl":"https://wondersofwildlife.org","price":"$39.95/adult, $24.95/child (est.)","photos":["assets/midwest-west/springfield-mo-city/attr1-1.jpg","assets/midwest-west/springfield-mo-city/attr1-2.jpg","assets/midwest-west/springfield-mo-city/attr1-3.jpg","assets/midwest-west/springfield-mo-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wonders%20of%20Wildlife%20National%20Museum%20%26%20Aquarium%20Springfield%20MO"},{"name":"Fantastic Caverns","description":"America's only ride-through cave: relax in a Jeep-drawn tram as you glide past towering stalactites and underground formations. The narrated 55-minute tour is easy for all ages and abilities.","officialUrl":"https://www.fantasticcaverns.com","price":"$32/adult, $19/child (est.)","photos":["assets/midwest-west/springfield-mo-city/attr2-1.jpg","assets/midwest-west/springfield-mo-city/attr2-2.jpg","assets/midwest-west/springfield-mo-city/attr2-3.jpg","assets/midwest-west/springfield-mo-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fantastic%20Caverns%20Springfield%20MO"},{"name":"Dickerson Park Zoo","description":"A 100+ acre zoo home to elephants, giraffes, lions, and cheetahs, with a strong conservation focus. The giraffe feeding experience and the train ride make it a family favorite.","officialUrl":"https://www.dickersonparkzoo.org","price":"$19/adult, $14/child (est.)","photos":["assets/midwest-west/springfield-mo-city/attr3-1.jpg","assets/midwest-west/springfield-mo-city/attr3-2.jpg","assets/midwest-west/springfield-mo-city/attr3-3.jpg","assets/midwest-west/springfield-mo-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dickerson%20Park%20Zoo%20Springfield%20MO"},{"name":"Route 66 Car Museum","description":"In the birthplace of Route 66, a collection of classic and vintage cars \u2014 Corvettes, muscle cars, and movie vehicles \u2014 surrounded by Mother Road memorabilia. A must for car fans, fun for everyone.","officialUrl":"https://www.66carmuseum.com","price":"$15/adult, $7/child (est.)","photos":["assets/midwest-west/springfield-mo-city/attr4-1.jpg","assets/midwest-west/springfield-mo-city/attr4-2.jpg","assets/midwest-west/springfield-mo-city/attr4-3.jpg","assets/midwest-west/springfield-mo-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Route%2066%20Car%20Museum%20Springfield%20MO"},{"name":"Discovery Center of Springfield","description":"A hands-on science center for kids: climb the multilevel structures, dig for dinosaurs, experiment with water physics, and explore the traveling exhibits. Great for ages 2\u201312.","officialUrl":"https://www.discoverycenter.org","price":"$14/person (est.)","photos":["assets/midwest-west/springfield-mo-city/attr5-1.jpg","assets/midwest-west/springfield-mo-city/attr5-2.jpg","assets/midwest-west/springfield-mo-city/attr5-3.jpg","assets/midwest-west/springfield-mo-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Discovery%20Center%20of%20Springfield%20Springfield%20MO"}],"restaurants":[{"name":"Lambert's Cafe","detail":"Home of the throwed rolls \u2014 servers toss hot rolls across the room; huge Ozark comfort-food portions in nearby Ozark.","price":"$$"},{"name":"Hurts Donut","detail":"The 24-hour Springfield donut institution with wild creations \u2014 a sugar-fueled stop the kids will beg for.","price":"$"},{"name":"Gailey's Breakfast Cafe","detail":"A beloved downtown breakfast spot in a historic building \u2014 creative morning plates in a cozy setting.","price":"$$"}],"rainyDay":["Wonders of Wildlife \u2014 the entire aquarium and museum are indoors","Discovery Center of Springfield \u2014 hands-on indoor play for kids","Route 66 Car Museum \u2014 classic cars and Mother Road history indoors"],"driveNotes":"Springfield is at the crossroads of I-44 and US-65, about 3 hours from St. Louis or Kansas City. Everything is 15 minutes apart; parking is easy and free at most attractions. Lambert's Cafe in Ozark draws big waits \u2014 go at off-hours or put your name in early.","related":["branson-mo-family","st-louis-mo-city","lake-ozarks-mo-lake"],"imageAsset":"assets/midwest-west/springfield-mo-city/hero.jpg"},{"id":"lake-ozarks-mo-lake","title":"Lake of the Ozarks, MO: Three-Day Lake Getaway","destination":"Osage Beach, MO","state":"MO","stateName":"Missouri","region":"Ozarks","days":3,"tripType":"lake getaway","interests":["family","outdoors","nature","scenic"],"budget":950,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Missouri's lake playground: castle ruins, caves, waterparks, and 1,150 miles of shoreline.","overview":"With more shoreline than the California coast, Lake of the Ozarks is the Midwest's premier lake destination. Hike to a ruined stone castle at Ha Ha Tonka, tour a cave by the lake, scream down waterpark slides, and stand atop the dam that made it all possible. It's a water-lover's trip with enough land adventures to fill the gaps. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Explore the castle ruins at Ha Ha Tonka State Park","Swim and boat on 54,000 acres of lake","Tour Bridal Cave by the water","Slide all day at Big Surf Waterpark","Walk across historic Bagnell Dam"],"bestSeason":"May\u2013September","familyFriendly":"Best for ages 4+. Ha Ha Tonka's trails have stairs and bluff edges \u2014 keep little ones close; the waterpark suits all ages.","lat":38.13779,"lng":-92.63598,"itinerary":[{"day":1,"title":"Ha Ha Tonka Day","morning":{"stop":"Ha Ha Tonka State Park","description":"Missouri's most magical state park: hike the trail to the stone ruins of a 1900s castle overlooking the lake, then descend to the natural bridge and the spring. The trails involve stairs but the payoff views are worth it.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Lake swimming","description":"Cool off at the park's lake access or head to a public beach. The spring-fed water is refreshing, and the bluff scenery beats any pool.","cost":"Free (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner in Osage Beach","description":"The Osage Beach strip has tons of family restaurants. After dinner, walk the lakefront and watch the boats \u2014 summer evenings here buzz with energy.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Waterpark and Caves","morning":{"stop":"Big Surf Waterpark","description":"A full waterpark day: wave pool, lazy river, slides from mild to wild, and a big kiddie splash area. Arrive at opening to claim shade \u2014 summer days sell out.","cost":"$40/person (est.)","time":"10:00 AM \u2013 2:00 PM"},"afternoon":{"stop":"Bridal Cave","description":"Drive to nearby Camdenton for a guided tour of Bridal Cave, famous for its massive columns and the underground Mystery Lake. The 60-minute tour is an easy walk and a cool break from the heat.","cost":"$24/adult, $14/child (est.)","time":"3:00 PM \u2013 4:30 PM"},"evening":{"stop":"Bagnell Dam strip","description":"Walk across the 1931 Bagnell Dam that created the lake, then browse the shops and fudge stores on the historic Bagnell Dam Strip. Dinner with a lake view caps the day.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":3,"title":"Lake Day","morning":{"stop":"Morning on the lake","description":"Rent a pontoon for a half day and explore the lake's endless coves. Swim off the boat, tube behind it, or just cruise \u2014 with 1,150 miles of shoreline, you won't see it all, and that's fine.","cost":"$250\u2013$350 half-day pontoon (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Lake of the Ozarks State Park","description":"Missouri's largest state park: hike the trails, visit the Ozark Caverns (a separate small cave tour), or swim at the public beach. The park's scale means room to breathe even on busy weekends.","cost":"Free; Ozark Caverns tour $12/adult (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Farewell dinner on the water","description":"End at a lakeside restaurant with a deck over the water. Watch the sun sink behind the hills \u2014 the lake's best nightly show, and it's free.","cost":"$60\u2013$80 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Ha Ha Tonka State Park","description":"A ruined 1900s stone castle on a bluff above the lake, plus a natural bridge, springs, and sinkholes. The trails through oak forest to the castle ruins feel like discovering a lost world.","officialUrl":"https://mostateparks.com/park/ha-ha-tonka-state-park","price":"Free (est.)","photos":["assets/midwest-west/lake-ozarks-mo-lake/attr1-1.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr1-2.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr1-3.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ha%20Ha%20Tonka%20State%20Park%20Camdenton%20MO"},{"name":"Lake of the Ozarks State Park","description":"Missouri's biggest state park: 17,000+ acres of Ozark hills with lake beaches, hiking and biking trails, and the Ozark Caverns tour. The park's size keeps it peaceful even in peak season.","officialUrl":"https://mostateparks.com/park/lake-ozarks-state-park","price":"Free; Ozark Caverns tour $12/adult (est.)","photos":["assets/midwest-west/lake-ozarks-mo-lake/attr2-1.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr2-2.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr2-3.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20of%20the%20Ozarks%20State%20Park%20Kaiser%20MO"},{"name":"Bagnell Dam","description":"The 1931 dam that created the lake \u2014 walk across it for views of the Osage River below, then browse the historic strip of shops and fudge stores at its base. An engineering marvel with a tourist-town soul.","officialUrl":"https://www.ameren.com","price":"Free (est.)","photos":["assets/midwest-west/lake-ozarks-mo-lake/attr3-1.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr3-2.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr3-3.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bagnell%20Dam%20Lake%20Ozark%20MO"},{"name":"Big Surf Waterpark","description":"The lake area's big waterpark: wave pool, lazy river, tube slides, and a kiddie lagoon. A full day of wet fun that pairs perfectly with the lake itself.","officialUrl":"https://www.bigsurfwaterpark.com","price":"$40/person (est.)","photos":["assets/midwest-west/lake-ozarks-mo-lake/attr4-1.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr4-2.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr4-3.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Big%20Surf%20Waterpark%20Linn%20Creek%20MO"},{"name":"Bridal Cave","description":"A beautiful show cave on the lake's Thunder Mountain: giant columns, delicate soda straws, and the underground Mystery Lake. The hour-long guided tour is an easy, cool escape on hot days.","officialUrl":"https://www.bridalcave.com","price":"$24/adult, $14/child (est.)","photos":["assets/midwest-west/lake-ozarks-mo-lake/attr5-1.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr5-2.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr5-3.jpg","assets/midwest-west/lake-ozarks-mo-lake/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bridal%20Cave%20Camdenton%20MO"}],"restaurants":[{"name":"JB Hook's","detail":"The lake's classic seafood and steak house with a big deck over the water \u2014 arrive by boat or car.","price":"$$$"},{"name":"Baxter's Lakeside Grille","detail":"Casual lakeside dining with live music in summer; burgers, sandwiches, and sunset views.","price":"$$"},{"name":"Wobbly Boots Roadhouse","detail":"A fun, sprawling roadhouse with Ozark comfort food, a big menu, and live music \u2014 great for groups with kids.","price":"$$"}],"rainyDay":["Bridal Cave \u2014 the guided tour is underground and weatherproof","Ozark Caverns at Lake of the Ozarks State Park \u2014 another indoor cave tour","The shops and indoor attractions of the Bagnell Dam Strip"],"driveNotes":"Osage Beach is 2.5 hours from St. Louis or Kansas City via US-54. Summer weekends bring heavy traffic on the main strip \u2014 use the side roads the locals favor. Book pontoon rentals and waterpark tickets ahead for July weekends; state park access is free and plentiful.","related":["branson-mo-family","brainerd-mn-lakes","okoboji-ia-lakes"],"imageAsset":"assets/midwest-west/lake-ozarks-mo-lake/hero.jpg"},{"id":"wichita-ks-city","title":"Wichita, KS: Three-Day City Adventure","destination":"Wichita, KS","state":"KS","stateName":"Kansas","region":"South Central Kansas","days":3,"tripType":"city adventure","interests":["family","museums","food","outdoors"],"budget":850,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Kansas's biggest city: a top-ranked zoo, Old West streets, and the Keeper of the Plains at sunset.","overview":"Wichita surprises first-time visitors: a nationally ranked zoo, beautiful botanical gardens, a Wild West museum town, and the iconic Keeper of the Plains sculpture where two rivers meet. It's affordable, easy to navigate, and full of the kind of attractions kids actually enjoy. Three days covers the highlights with room to breathe. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Come face to face with tigers at the Sedgwick County Zoo","Wander 18 themed gardens at Botanica Wichita","Step into the 1860s at Old Cowtown Museum","Watch the fire pots light at the Keeper of the Plains","Feed lorikeets at Tanganyika Wildlife Park"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The zoo is large \u2014 rent a stroller or plan rest stops; Old Cowtown's dirt streets suit sturdy shoes.","lat":37.68749,"lng":-97.33558,"itinerary":[{"day":1,"title":"Zoo Day","morning":{"stop":"Sedgwick County Zoo","description":"Kansas's top zoo and one of America's largest: tigers, gorillas, elephants, and the popular Australia walkabout. Arrive at opening and head to the big cats first \u2014 they're most active in the cool morning.","cost":"$24.95/adult, $16.95/child (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Botanica Wichita","description":"After lunch, unwind at these 18 acres of themed gardens \u2014 the butterfly house, the children's garden with its treehouse, and the koi ponds. It's shady, pretty, and a perfect post-zoo cooldown.","cost":"$12/adult, $8/child (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Keeper of the Plains at sunset","description":"Drive to the confluence of the Arkansas and Little Arkansas rivers for the 44-foot Keeper of the Plains sculpture. At sunset (and on summer evenings), the fire pots light in a beautiful ceremony \u2014 arrive 30 minutes early for a good spot.","cost":"Free (est.)","time":"6:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Old West Day","morning":{"stop":"Old Cowtown Museum","description":"Step into 1860s Wichita: a living-history village with 50+ historic buildings, costumed interpreters, and live gunfight reenactments. Kids can try old-fashioned games and watch the blacksmith work.","cost":"$11/adult, $8/child (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Museum of World Treasures","description":"Three floors of the unexpected: dinosaur skeletons, Egyptian mummies, and a Berlin Wall section. It's quirky, dense, and kids love the variety \u2014 there's always something new around the corner.","cost":"$12.95/adult, $7.95/child (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Old Town dinner","description":"Wichita's Old Town warehouse district has family-friendly restaurants and a lively evening scene. Grab dinner and walk the brick streets \u2014 the area is very walkable.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Wildlife Park and Farewell","morning":{"stop":"Tanganyika Wildlife Park","description":"Drive 20 minutes to Goddard for this interactive wildlife park: feed lorikeets, meet penguins up close, and take a behind-the-scenes tour. The encounters feel personal \u2014 a highlight for animal-loving kids.","cost":"$29.95/adult, $24.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Wichita Art Museum or river trail","description":"Back in town, visit the free Wichita Art Museum's American art collection, or rent bikes and ride the Arkansas River trail. A relaxed afternoon before the drive home.","cost":"Free museum; bike rentals $15/hour (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell dinner","description":"End with Wichita comfort food \u2014 the city's diners and barbecue joints are excellent and cheap. Hit the road with full bellies.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Sedgwick County Zoo","description":"One of America's largest zoos, home to 3,000+ animals including tigers, gorillas, elephants, and orangutans. The Tiger Trek, the Australia walkabout, and the boat ride through the jungle building are standouts.","officialUrl":"https://www.scz.org","price":"$24.95/adult, $16.95/child (est.)","photos":["assets/midwest-west/wichita-ks-city/attr1-1.jpg","assets/midwest-west/wichita-ks-city/attr1-2.jpg","assets/midwest-west/wichita-ks-city/attr1-3.jpg","assets/midwest-west/wichita-ks-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sedgwick%20County%20Zoo%20Wichita%20KS"},{"name":"Botanica Wichita","description":"Eighteen acres of themed gardens: a butterfly house, a Shakespeare garden, koi ponds, and a wonderful children's garden with treehouses. Shady, beautiful, and a calm counterpoint to the zoo.","officialUrl":"https://www.botanica.org","price":"$12/adult, $8/child (est.)","photos":["assets/midwest-west/wichita-ks-city/attr2-1.jpg","assets/midwest-west/wichita-ks-city/attr2-2.jpg","assets/midwest-west/wichita-ks-city/attr2-3.jpg","assets/midwest-west/wichita-ks-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Botanica%20Wichita%20Wichita%20KS"},{"name":"Museum of World Treasures","description":"Three floors spanning dinosaurs to the Berlin Wall: mummies, fossils, presidential artifacts, and military history. Eclectic and dense \u2014 kids find something amazing in every room.","officialUrl":"https://www.worldtreasures.org","price":"$12.95/adult, $7.95/child (est.)","photos":["assets/midwest-west/wichita-ks-city/attr3-1.jpg","assets/midwest-west/wichita-ks-city/attr3-2.jpg","assets/midwest-west/wichita-ks-city/attr3-3.jpg","assets/midwest-west/wichita-ks-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Museum%20of%20World%20Treasures%20Wichita%20KS"},{"name":"Old Cowtown Museum","description":"A living-history village recreating 1860s\u201370s Wichita with 50+ period buildings, costumed interpreters, and reenactments. Watch the blacksmith, tour the saloon, and catch the gunfight show.","officialUrl":"https://www.oldcowtown.org","price":"$11/adult, $8/child (est.)","photos":["assets/midwest-west/wichita-ks-city/attr4-1.jpg","assets/midwest-west/wichita-ks-city/attr4-2.jpg","assets/midwest-west/wichita-ks-city/attr4-3.jpg","assets/midwest-west/wichita-ks-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Old%20Cowtown%20Museum%20Wichita%20KS"},{"name":"Tanganyika Wildlife Park","description":"An interactive wildlife park 20 minutes west of Wichita: feed lorikeets and giraffes, meet penguins, and join behind-the-scenes encounters. Smaller and more hands-on than a traditional zoo.","officialUrl":"https://www.twpark.com","price":"$29.95/adult, $24.95/child (est.)","photos":["assets/midwest-west/wichita-ks-city/attr5-1.jpg","assets/midwest-west/wichita-ks-city/attr5-2.jpg","assets/midwest-west/wichita-ks-city/attr5-3.jpg","assets/midwest-west/wichita-ks-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tanganyika%20Wildlife%20Park%20Goddard%20KS"}],"restaurants":[{"name":"Doo-Dah Diner","detail":"Wichita's beloved breakfast-and-burger diner \u2014 huge portions, funky d\u00e9cor, and a menu the kids will love.","price":"$$"},{"name":"Knolla's Pizza","detail":"A Wichita institution since 1955 serving thin-crust pizza; the family atmosphere is pure Midwest.","price":"$$"},{"name":"Old Mill Tasty Shop","detail":"An old-fashioned soda fountain and diner downtown \u2014 malts, burgers, and vintage charm.","price":"$"}],"rainyDay":["Museum of World Treasures \u2014 three floors of dinosaurs, mummies, and history","Wichita Art Museum \u2014 free American art in a beautiful riverside building","Tanganyika Wildlife Park \u2014 many encounters are under cover"],"driveNotes":"Wichita is at the junction of I-35 and US-400, about 3 hours from Kansas City or Oklahoma City. The city is flat and easy to navigate; most attractions are 15 minutes apart with free parking. The Keeper of the Plains fire ceremony runs nightly in summer \u2014 check times before you go.","related":["kansas-city-mo-city","hutchinson-ks-space","topeka-ks-city"],"imageAsset":"assets/midwest-west/wichita-ks-city/hero.jpg"},{"id":"hutchinson-ks-space","title":"Hutchinson, KS: Two-Day Space & Underground Adventure","destination":"Hutchinson, KS","state":"KS","stateName":"Kansas","region":"South Central Kansas","days":2,"tripType":"space adventure","interests":["family","museums","outdoors"],"budget":600,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"Touch a real moon rock, then descend 650 feet into a salt mine \u2014 all in one small Kansas city.","overview":"Hutchinson holds two of the Midwest's most extraordinary attractions: the Kansas Cosmosphere, a Smithsonian-affiliated space museum with real flown spacecraft, and Strataca, a working salt mine 650 feet underground. Together they make a jaw-dropping two-day trip that kids talk about for years. Add a pretty nature center and parks, and Hutchinson earns its spot. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["See real Apollo capsules at the Kansas Cosmosphere","Descend 650 feet into the Strataca salt mine","Walk the trails at Dillon Nature Center","Picnic and paddleboat at Carey Park","Meet the animals at the free Hutchinson Zoo"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 5+. The salt mine is 68\u00b0F year-round \u2014 bring jackets; both big attractions are fully accessible.","lat":38.05725,"lng":-97.93225,"itinerary":[{"day":1,"title":"Space Day","morning":{"stop":"Kansas Cosmosphere and Space Center","description":"Give this world-class museum the whole morning: the Apollo 13 command module, a real SR-71 Blackbird, Soviet spacecraft, and a planetarium. The guided tours bring the space race to life \u2014 book the earliest tour slot.","cost":"$26/adult, $16/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Cosmosphere continued","description":"After lunch at the caf\u00e9, catch a planetarium show and explore the hands-on Hall of Space. The museum shop is dangerously good \u2014 set a souvenir budget before you enter.","cost":"Planetarium $8/person (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Hutchinson","description":"Downtown Hutchinson has family-friendly restaurants within walking distance of the Cosmosphere. Try the famous broasted chicken at the Anchor Inn \u2014 a local institution.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Underground and Outdoors","morning":{"stop":"Strataca","description":"Descend 650 feet in the mine shaft elevator into a working salt mine. The 90-minute guided tram tour winds past glittering salt walls, mining equipment, and underground exhibits \u2014 including movie memorabilia stored in the mine's vaults. Bring a jacket; it's 68\u00b0F down there.","cost":"$29/adult, $19/child (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Dillon Nature Center","description":"Above ground again, visit this 100-acre nature center with trails, ponds, and a great visitor center. The butterfly garden blooms in summer, and the trails are easy for all ages.","cost":"Free (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Carey Park and farewell","description":"End at Carey Park \u2014 paddleboats on the lake, a playground, and the small free Hutchinson Zoo. A relaxed evening before the drive home.","cost":"Free; paddleboats $10/half hour (est.)","time":"4:00 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Kansas Cosmosphere and Space Center","description":"A Smithsonian-affiliated space museum with the largest combined collection of US and Russian space artifacts in the world: the Apollo 13 capsule, a flown SR-71, and real moon rocks. The planetarium and guided tours are superb.","officialUrl":"https://www.cosmo.org","price":"$26/adult, $16/child (est.)","photos":["assets/midwest-west/hutchinson-ks-space/attr1-1.jpg","assets/midwest-west/hutchinson-ks-space/attr1-2.jpg","assets/midwest-west/hutchinson-ks-space/attr1-3.jpg","assets/midwest-west/hutchinson-ks-space/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kansas%20Cosmosphere%20and%20Space%20Center%20Hutchinson%20KS"},{"name":"Strataca","description":"A working salt mine 650 feet below Kansas: ride the shaft elevator down, then tour glittering tunnels by tram. See mining history, underground vaults, and the famous salt formations \u2014 an only-in-Kansas experience.","officialUrl":"https://www.strataca.com","price":"$29/adult, $19/child (est.)","photos":["assets/midwest-west/hutchinson-ks-space/attr2-1.jpg","assets/midwest-west/hutchinson-ks-space/attr2-2.jpg","assets/midwest-west/hutchinson-ks-space/attr2-3.jpg","assets/midwest-west/hutchinson-ks-space/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Strataca%20Hutchinson%20KS"},{"name":"Dillon Nature Center","description":"One hundred acres of prairie, woodland, and ponds with easy trails and an excellent visitor center. The wildflower displays and butterfly garden shine in summer; the trails are perfect for young hikers.","officialUrl":"https://www.hutchrec.com/dillon-nature-center/","price":"Free (est.)","photos":["assets/midwest-west/hutchinson-ks-space/attr3-1.jpg","assets/midwest-west/hutchinson-ks-space/attr3-2.jpg","assets/midwest-west/hutchinson-ks-space/attr3-3.jpg","assets/midwest-west/hutchinson-ks-space/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dillon%20Nature%20Center%20Hutchinson%20KS"},{"name":"Carey Park","description":"Hutchinson's big central park: paddleboats on the lake, playgrounds, picnic shelters, and the free Hutchinson Zoo. A classic American park day, all in one place.","officialUrl":"https://www.hutchgov.com","price":"Free; paddleboats $10/half hour (est.)","photos":["assets/midwest-west/hutchinson-ks-space/attr4-1.jpg","assets/midwest-west/hutchinson-ks-space/attr4-2.jpg","assets/midwest-west/hutchinson-ks-space/attr4-3.jpg","assets/midwest-west/hutchinson-ks-space/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Carey%20Park%20Hutchinson%20KS"},{"name":"Hutchinson Zoo","description":"A small, free zoo in Carey Park with prairie dogs, bison, monkeys, and a popular otter exhibit. Compact enough for little legs \u2014 a sweet bonus stop, not a full-day destination.","officialUrl":"https://www.hutchgov.com","price":"Free (est.)","photos":["assets/midwest-west/hutchinson-ks-space/attr5-1.jpg","assets/midwest-west/hutchinson-ks-space/attr5-2.jpg","assets/midwest-west/hutchinson-ks-space/attr5-3.jpg","assets/midwest-west/hutchinson-ks-space/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hutchinson%20Zoo%20Hutchinson%20KS"}],"restaurants":[{"name":"Roy's Hickory Pit BBQ","detail":"A Hutchinson barbecue institution \u2014 hickory-smoked meats in a casual, family-friendly dining room.","price":"$$"},{"name":"Anchor Inn","detail":"Famous for its broasted chicken since 1964; a Hutchinson landmark the locals swear by.","price":"$$"},{"name":"Carriage Crossing Restaurant","detail":"In nearby Yoder, an Amish-country restaurant serving family-style fried chicken, homemade pies, and bulk-food shopping.","price":"$$"}],"rainyDay":["Kansas Cosmosphere and Space Center \u2014 a full indoor day of space history","Strataca \u2014 the salt mine tour is underground and weatherproof","Hutchinson's downtown shops and the Cosmosphere's planetarium shows"],"driveNotes":"Hutchinson is 1 hour northwest of Wichita on US-50. Both big attractions are on the east side of town, minutes apart \u2014 you can walk between the Cosmosphere and downtown restaurants. Book Strataca tours ahead in summer; the mine stays 68\u00b0F year-round so bring layers.","related":["wichita-ks-city","topeka-ks-city","pella-ia-dutch"],"imageAsset":"assets/midwest-west/hutchinson-ks-space/hero.jpg"},{"id":"topeka-ks-city","title":"Topeka, KS: Two-Day Capital Getaway","destination":"Topeka, KS","state":"KS","stateName":"Kansas","region":"Northeast Kansas","days":2,"tripType":"capital getaway","interests":["family","museums","historical-sites","outdoors"],"budget":550,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"Kansas's capital: a copper-domed capitol, a top children's museum, and trains at the history museum.","overview":"Topeka is an easy, affordable capital-city weekend: tour one of America's most beautiful state capitols, let the kids loose in an excellent children's discovery center, and meet the animals at a conservation-focused zoo. The state history museum's walk-through 1950s diner and giant steam locomotive are the wild cards. Two relaxed days, minimal driving. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Climb to the top of the Kansas State Capitol dome","Play and build at the Kansas Children's Discovery Center","Meet the animals at the Topeka Zoo","Explore Kansas history at the Kansas Museum of History","Paddleboat and picnic at Lake Shawnee"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The Capitol dome tour has 296 steps \u2014 exciting for kids 6+, tough for toddlers; the zoo and discovery center suit all ages.","lat":39.04926,"lng":-95.67119,"itinerary":[{"day":1,"title":"Capitol and Discovery","morning":{"stop":"Kansas State Capitol","description":"Tour the stunning 37-year-built Capitol with its copper dome \u2014 you can climb the 296 steps to the very top for a panoramic view (kids 6+ love it). The murals, marble, and historic chambers make the free tour feel grand.","cost":"Free tours; dome tour free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Kansas Children's Discovery Center","description":"One of the region's best children's museums: build in the construction zone, splash in the water area, climb the treehouse, and explore the outdoor play garden. Plan on 2\u20133 hours minimum.","cost":"$11/person (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in NOTO","description":"The North Topeka Arts District (NOTO) has galleries, colorful murals, and family-friendly restaurants. An evening stroll here is a lovely way to end day one.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo and Daredevils","morning":{"stop":"Topeka Zoo & Conservation Center","description":"A compact, conservation-focused zoo with lions, elephants, giraffes, and a tropical rainforest building. Small enough to see in a few hours \u2014 perfect for younger kids who tire at big zoos.","cost":"$14.50/adult, $11.50/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Kansas Museum of History","description":"The state's flagship history museum: walk through a full-size 1950s diner, see a real steam locomotive, and explore exhibits from Bleeding Kansas to the present. The hands-on areas and the big trains make it a hit with kids.","cost":"$10/adult, $5/child (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Lake Shawnee and farewell","description":"End at Lake Shawnee: paddleboat on the lake, walk the gardens, and let the kids run the playground. A picnic dinner here is the perfect low-key finale.","cost":"Free; paddleboats $10/half hour (est.)","time":"4:00 PM \u2013 6:30 PM"}}],"attractions":[{"name":"Kansas State Capitol","description":"A French Renaissance masterpiece with a copper dome you can climb \u2014 296 steps to a breathtaking view. Free guided tours cover the murals, the historic chambers, and 37 years of construction history.","officialUrl":"https://www.kshs.org","price":"Free tours (est.)","photos":["assets/midwest-west/topeka-ks-city/attr1-1.jpg","assets/midwest-west/topeka-ks-city/attr1-2.jpg","assets/midwest-west/topeka-ks-city/attr1-3.jpg","assets/midwest-west/topeka-ks-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kansas%20State%20Capitol%20Topeka%20KS"},{"name":"Kansas Children's Discovery Center","description":"A top-tier children's museum with indoor and outdoor play: construction zone, water tables, climbing structures, and a treehouse. Designed for ages 1\u201312, with enough to fill half a day easily.","officialUrl":"https://www.kansasdiscovery.org","price":"$11/person (est.)","photos":["assets/midwest-west/topeka-ks-city/attr2-1.jpg","assets/midwest-west/topeka-ks-city/attr2-2.jpg","assets/midwest-west/topeka-ks-city/attr2-3.jpg","assets/midwest-west/topeka-ks-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kansas%20Children%27s%20Discovery%20Center%20Topeka%20KS"},{"name":"Topeka Zoo & Conservation Center","description":"A 36-acre zoo focused on conservation: lions, elephants, giraffes, and the indoor Tropical Rainforest. Compact and shady \u2014 an easy, uncrowded zoo experience for families.","officialUrl":"https://www.topekazoo.org","price":"$14.50/adult, $11.50/child (est.)","photos":["assets/midwest-west/topeka-ks-city/attr3-1.jpg","assets/midwest-west/topeka-ks-city/attr3-2.jpg","assets/midwest-west/topeka-ks-city/attr3-3.jpg","assets/midwest-west/topeka-ks-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Topeka%20Zoo%20%26%20Conservation%20Center%20Topeka%20KS"},{"name":"Kansas Museum of History","description":"The Kansas Historical Society's flagship museum: a walk-through 1950s diner, a massive steam locomotive, and exhibits tracing Kansas from prehistory through the civil rights era. Engaging, spacious, and great for kids.","officialUrl":"https://www.kshs.org","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/topeka-ks-city/attr4-1.jpg","assets/midwest-west/topeka-ks-city/attr4-2.jpg","assets/midwest-west/topeka-ks-city/attr4-3.jpg","assets/midwest-west/topeka-ks-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kansas%20Museum%20of%20History%20Topeka%20KS"},{"name":"Lake Shawnee","description":"Topeka's 1,100-acre lake park: paddleboats, beaches, gardens, trails, and playgrounds. The Ted Ensley Gardens bloom beautifully in season \u2014 a classic family park day.","officialUrl":"https://www.snco.gov","price":"Free; paddleboats $10/half hour (est.)","photos":["assets/midwest-west/topeka-ks-city/attr5-1.jpg","assets/midwest-west/topeka-ks-city/attr5-2.jpg","assets/midwest-west/topeka-ks-city/attr5-3.jpg","assets/midwest-west/topeka-ks-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20Shawnee%20Topeka%20KS"}],"restaurants":[{"name":"The Pad","detail":"A Topeka Mexican-food institution \u2014 the margaritas are famous, but the family-friendly menu keeps kids happy too.","price":"$$"},{"name":"Blind Tiger Brewery & Restaurant","detail":"A downtown brewpub in a historic building with great burgers and house-brewed root beer for the kids.","price":"$$"},{"name":"Herman's Meat & Smokehouse","detail":"A Topeka smokehouse legend for barbecue and smoked meats \u2014 casual, hearty, and affordable.","price":"$$"}],"rainyDay":["Kansas Children's Discovery Center \u2014 indoor and covered play for hours","Kansas Museum of History \u2014 trains, diners, and Kansas history indoors","Kansas State Capitol \u2014 free guided tours of the grand interiors"],"driveNotes":"Topeka is 1 hour west of Kansas City on I-70. Downtown parking is easy; the Capitol, zoo, and discovery center are all within 10 minutes of each other. Lake Shawnee is on the southeast side \u2014 a quick drive from downtown.","related":["wichita-ks-city","hutchinson-ks-space","kansas-city-mo-city"],"imageAsset":"assets/midwest-west/topeka-ks-city/hero.jpg"},{"id":"dodge-city-ks-western","title":"Dodge City, KS: Two-Day Wild West Getaway","destination":"Dodge City, KS","state":"KS","stateName":"Kansas","region":"Western Kansas","days":2,"tripType":"wild west getaway","interests":["family","historical-sites","museums","outdoors"],"budget":500,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"The real Wild West: Boot Hill, gunfights, and wagon ruts still visible in the prairie.","overview":"Dodge City leans into its legend \u2014 'the wickedest little city in America' \u2014 and families eat it up. The Boot Hill Museum recreates 1870s Front Street complete with gunfight reenactments and a saloon variety show, the zoo is a pleasant surprise, and actual Santa Fe Trail wagon ruts still scar the prairie nearby. It's a fun, compact two days deep in western Kansas. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Watch a gunfight reenactment on Boot Hill's Front Street","See the Long Branch Saloon variety show","Meet the animals at Wright Park Zoo","Walk the actual Santa Fe Trail ruts","Pose with the Wyatt Earp statue downtown"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 5+. The gunfight shows use blanks (loud!) \u2014 bring ear protection for sensitive kids; the museum and zoo suit all ages.","lat":37.75267,"lng":-100.01891,"itinerary":[{"day":1,"title":"Boot Hill Day","morning":{"stop":"Boot Hill Museum","description":"Spend the morning at this excellent Wild West museum: 1870s Front Street with original buildings, the Boot Hill cemetery, and exhibits on Wyatt Earp, Bat Masterson, and the cattle-drive era. Don't miss the 11 AM gunfight reenactment on the street.","cost":"$18/adult, $10/child (est.)","time":"9:30 AM \u2013 1:00 PM"},"afternoon":{"stop":"Boot Hill continued","description":"After lunch, explore the museum galleries \u2014 the General Store, the saloon, and the hands-on kids' exhibits. The afternoon variety show in the Long Branch Saloon (can-can dancers and comedy) is a hoot for all ages.","cost":"Variety show $15/adult, $8/child (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Downtown Dodge City","description":"Walk the downtown Trail of Fame medallions honoring Western legends, pose with the Wyatt Earp statue, and have dinner at a classic steakhouse. The sunset over the prairie is spectacular.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo and Trail Ruts","morning":{"stop":"Wright Park Zoo","description":"A small, free city zoo in beautiful Wright Park: monkeys, big cats, reptiles, and a popular prairie-dog town. It's an easy, shady morning \u2014 pair it with the park's playground and pond.","cost":"Free (est.)","time":"9:30 AM \u2013 11:30 AM"},"afternoon":{"stop":"Santa Fe Trail Ruts","description":"Drive 9 miles west to see actual wagon ruts carved into the prairie by Santa Fe Trail traffic in the 1800s \u2014 a National Historic Landmark. Standing in the ruts, imagining the wagon trains, gives kids chills.","cost":"Free (est.)","time":"12:30 PM \u2013 2:30 PM"},"evening":{"stop":"Carnegie Center for the Arts and farewell","description":"Back in town, visit the Carnegie Center's galleries in the historic library building, then have a farewell dinner. Dodge City's sunsets over the Arkansas River valley are the perfect goodbye.","cost":"Free gallery; dinner $50\u2013$70 for four (est.)","time":"4:00 PM \u2013 7:00 PM"}}],"attractions":[{"name":"Boot Hill Museum","description":"The premier Wild West museum: a recreated 1870s Front Street with original buildings, the Boot Hill cemetery, gunfight reenactments, and the Long Branch Saloon variety show. The real Dodge City history is wilder than the legends.","officialUrl":"https://www.boothill.org","price":"$18/adult, $10/child (est.)","photos":["assets/midwest-west/dodge-city-ks-western/attr1-1.jpg","assets/midwest-west/dodge-city-ks-western/attr1-2.jpg","assets/midwest-west/dodge-city-ks-western/attr1-3.jpg","assets/midwest-west/dodge-city-ks-western/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Boot%20Hill%20Museum%20Dodge%20City%20KS"},{"name":"Wright Park Zoo","description":"A free, well-kept city zoo in historic Wright Park: big cats, primates, reptiles, and an active prairie-dog town. Shady paths, a playground, and a pond make it a lovely family morning.","officialUrl":"https://www.dodgecity.org","price":"Free (est.)","photos":["assets/midwest-west/dodge-city-ks-western/attr2-1.jpg","assets/midwest-west/dodge-city-ks-western/attr2-2.jpg","assets/midwest-west/dodge-city-ks-western/attr2-3.jpg","assets/midwest-west/dodge-city-ks-western/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wright%20Park%20Zoo%20Dodge%20City%20KS"},{"name":"Santa Fe Trail Ruts","description":"Nine miles west of town, deep wagon ruts from 1800s Santa Fe Trail traffic still scar the prairie \u2014 a National Historic Landmark. An interpretive pulloff explains the trail; walking the ruts is unforgettable.","officialUrl":"https://www.nps.gov/safe","price":"Free (est.)","photos":["assets/midwest-west/dodge-city-ks-western/attr3-1.jpg","assets/midwest-west/dodge-city-ks-western/attr3-2.jpg","assets/midwest-west/dodge-city-ks-western/attr3-3.jpg","assets/midwest-west/dodge-city-ks-western/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Santa%20Fe%20Trail%20Ruts%20Dodge%20City%20KS"},{"name":"Carnegie Center for the Arts","description":"Housed in Dodge City's 1906 Carnegie library, this arts center hosts rotating exhibitions, classes, and the town's cultural events. A calm, air-conditioned counterpoint to the Wild West bustle.","officialUrl":"https://www.dodgecity.org","price":"Free (est.)","photos":["assets/midwest-west/dodge-city-ks-western/attr4-1.jpg","assets/midwest-west/dodge-city-ks-western/attr4-2.jpg","assets/midwest-west/dodge-city-ks-western/attr4-3.jpg","assets/midwest-west/dodge-city-ks-western/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Carnegie%20Center%20for%20the%20Arts%20Dodge%20City%20KS"}],"restaurants":[{"name":"Casey's Cowtown Club","detail":"The classic Dodge City steakhouse \u2014 big steaks, Western d\u00e9cor, and a salad bar; the town's special-occasion spot.","price":"$$"},{"name":"Dodge House Restaurant","detail":"A comfortable family restaurant known for hearty breakfasts and homestyle dinners near the Boot Hill area.","price":"$$"},{"name":"Central Station Bar & Grill","detail":"A lively downtown spot in the historic train station area \u2014 burgers, sandwiches, and local color.","price":"$$"}],"rainyDay":["Boot Hill Museum \u2014 most exhibits and the saloon show are indoors","Carnegie Center for the Arts \u2014 galleries in the historic library","Dodge City's downtown shops and the historic train depot area"],"driveNotes":"Dodge City is 2.5 hours west of Wichita on US-400/50 \u2014 deep in western Kansas. Gas up before the final stretch; services thin out west of town. Summer brings heat and wind \u2014 plan outdoor activities for mornings. The Trail Ruts site is 9 miles west on US-50 with a marked pulloff.","related":["flint-hills-ks-prairie","wichita-ks-city","scottsbluff-ne-history"],"imageAsset":"assets/midwest-west/dodge-city-ks-western/hero.jpg"},{"id":"flint-hills-ks-prairie","title":"Flint Hills, KS: Three-Day Prairie Adventure","destination":"Cottonwood Falls, KS","state":"KS","stateName":"Kansas","region":"Flint Hills","days":3,"tripType":"prairie adventure","interests":["family","outdoors","nature","scenic","historical-sites"],"budget":700,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"America's last great tallgrass prairie: bison, endless sky, and the prettiest small towns in Kansas.","overview":"The Flint Hills hold the largest remaining expanse of tallgrass prairie on Earth \u2014 rolling grasslands that once covered 170 million acres. Hike among bison at the Tallgrass Prairie National Preserve, explore a prairie discovery center, and wander limestone-courthouse towns that time forgot. It's a quiet, soul-filling trip for families who love big skies and open space. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Hike among bison at Tallgrass Prairie National Preserve","Explore the interactive Flint Hills Discovery Center","Watch the sunset over Konza Prairie","Tour a working 1860s limestone ranch at Pioneer Bluffs","See the 1873 Chase County Courthouse in Cottonwood Falls"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 6+. Prairie trails are exposed \u2014 bring sun protection, water, and bug spray; distances between towns are real.","lat":38.37327,"lng":-96.54031,"itinerary":[{"day":1,"title":"Tallgrass Prairie Day","morning":{"stop":"Tallgrass Prairie National Preserve","description":"Start at the visitor center, then hike the Southwind Nature Trail among the bison herd \u2014 seeing these giants on the open prairie is unforgettable. The historic Spring Hill Ranch house and 1881 limestone barn are worth the tour.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Preserve trails and picnic","description":"Picnic at the preserve, then hike the longer Fox Creek Trail through the tallgrass. In late summer the grass towers over kids' heads \u2014 bring a camera and plenty of water.","cost":"Free; picnic $30\u2013$40 (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Cottonwood Falls","description":"Drive into Cottonwood Falls, one of Kansas's prettiest small towns. Have dinner, walk the historic downtown, and admire the 1873 Chase County Courthouse \u2014 the oldest operating courthouse in Kansas.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:00 PM \u2013 8:00 PM"}},{"day":2,"title":"Discovery Center and Konza","morning":{"stop":"Flint Hills Discovery Center","description":"Drive 45 minutes to Manhattan for this excellent museum: an immersive prairie theater, hands-on exhibits about the tallgrass ecosystem, and a rooftop terrace. Kids love the underground 'roots' tunnel.","cost":"$12/adult, $7/child (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Konza Prairie Biological Station","description":"Hike the public trails at this 8,600-acre research prairie run by Kansas State. The loop trails climb to panoramic overlooks \u2014 in spring, the wildflowers are extraordinary, and bison roam the backcountry.","cost":"Free (est.)","time":"2:00 PM \u2013 5:00 PM"},"evening":{"stop":"Dinner in Manhattan","description":"Manhattan's downtown (the 'Little Apple') has family-friendly restaurants and a lively college-town feel. An easy evening after a day of prairie walking.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Ranches and Farewell","morning":{"stop":"Pioneer Bluffs","description":"Visit this working 1860s limestone ranch near Matfield Green: tour the historic buildings, meet the farm animals, and learn how ranching shaped the Flint Hills. The setting \u2014 big sky, stone barns \u2014 is pure Kansas.","cost":"$10/adult, $5/child (est.)","time":"10:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Chase County Courthouse and falls","description":"Back in Cottonwood Falls, tour the stunning 1873 courthouse \u2014 its walnut staircase and stonework are remarkable. Then cool off at the Cottonwood River falls just outside town.","cost":"Free (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Prairie sunset farewell","description":"End with a prairie sunset \u2014 drive to an overlook or just pull off a country road. The Flint Hills at golden hour, with grass swaying to the horizon, is the trip's lasting image.","cost":"Free (est.)","time":"6:00 PM \u2013 7:30 PM"}}],"attractions":[{"name":"Tallgrass Prairie National Preserve","description":"Nearly 11,000 acres of never-plowed tallgrass prairie with a roaming bison herd. Hike among the bison, tour the 1881 limestone ranch buildings, and experience the prairie as it was 200 years ago.","officialUrl":"https://www.nps.gov/tapr","price":"Free (est.)","photos":["assets/midwest-west/flint-hills-ks-prairie/attr1-1.jpg","assets/midwest-west/flint-hills-ks-prairie/attr1-2.jpg","assets/midwest-west/flint-hills-ks-prairie/attr1-3.jpg","assets/midwest-west/flint-hills-ks-prairie/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tallgrass%20Prairie%20National%20Preserve%20Strong%20City%20KS"},{"name":"Flint Hills Discovery Center","description":"An immersive museum celebrating the tallgrass prairie: a 15-minute prairie theater experience, hands-on ecology exhibits, and a rooftop terrace. The best indoor introduction to the Flint Hills.","officialUrl":"https://www.flinthillsdiscovery.org","price":"$12/adult, $7/child (est.)","photos":["assets/midwest-west/flint-hills-ks-prairie/attr2-1.jpg","assets/midwest-west/flint-hills-ks-prairie/attr2-2.jpg","assets/midwest-west/flint-hills-ks-prairie/attr2-3.jpg","assets/midwest-west/flint-hills-ks-prairie/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Flint%20Hills%20Discovery%20Center%20Manhattan%20KS"},{"name":"Konza Prairie Biological Station","description":"8,600 acres of native tallgrass prairie managed by Kansas State for research \u2014 with public hiking trails to stunning overlooks. Wildflowers in spring, golden grass in fall, and bison in the distance.","officialUrl":"https://www.konza.ksu.edu","price":"Free (est.)","photos":["assets/midwest-west/flint-hills-ks-prairie/attr3-1.jpg","assets/midwest-west/flint-hills-ks-prairie/attr3-2.jpg","assets/midwest-west/flint-hills-ks-prairie/attr3-3.jpg","assets/midwest-west/flint-hills-ks-prairie/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Konza%20Prairie%20Biological%20Station%20Manhattan%20KS"},{"name":"Pioneer Bluffs","description":"A working historic ranch on 19th-century limestone buildings: tour the ranch house, meet farm animals, and attend seasonal events. A living window into Flint Hills ranching life.","officialUrl":"https://www.pioneerbluffs.org","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/flint-hills-ks-prairie/attr4-1.jpg","assets/midwest-west/flint-hills-ks-prairie/attr4-2.jpg","assets/midwest-west/flint-hills-ks-prairie/attr4-3.jpg","assets/midwest-west/flint-hills-ks-prairie/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pioneer%20Bluffs%20Matfield%20Green%20KS"},{"name":"Chase County Courthouse","description":"The oldest operating courthouse in Kansas (1873): a stunning limestone building with a famous walnut staircase. Free tours reveal frontier justice stories; the downtown around it is pure small-town charm.","officialUrl":"https://www.kshs.org","price":"Free (est.)","photos":["assets/midwest-west/flint-hills-ks-prairie/attr5-1.jpg","assets/midwest-west/flint-hills-ks-prairie/attr5-2.jpg","assets/midwest-west/flint-hills-ks-prairie/attr5-3.jpg","assets/midwest-west/flint-hills-ks-prairie/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chase%20County%20Courthouse%20Cottonwood%20Falls%20KS"}],"restaurants":[{"name":"Hays House","detail":"In nearby Council Grove, Kansas's oldest restaurant (1857) \u2014 fried chicken and comfort food in a historic Santa Fe Trail building.","price":"$$"},{"name":"Grand Central Hotel Grill","detail":"Cottonwood Falls' historic hotel restaurant \u2014 the state's oldest continuously operating hotel, with a cozy grill.","price":"$$"},{"name":"The Chef","detail":"A beloved Manhattan caf\u00e9 known for creative breakfasts and lunches \u2014 perfect before or after the Discovery Center.","price":"$$"}],"rainyDay":["Flint Hills Discovery Center \u2014 immersive indoor prairie exhibits in Manhattan","Chase County Courthouse \u2014 tour the historic interiors in Cottonwood Falls","Pioneer Bluffs \u2014 historic ranch buildings with covered areas"],"driveNotes":"The Flint Hills stretch along I-35 and US-50 in eastern Kansas. Cottonwood Falls is 1.5 hours from Wichita or Kansas City. Towns are small and far apart \u2014 fill up gas and pack snacks. Cell service can be spotty on back roads; download maps offline.","related":["dodge-city-ks-western","sandhills-ne-nature","topeka-ks-city"],"imageAsset":"assets/midwest-west/flint-hills-ks-prairie/hero.jpg"},{"id":"omaha-ne-city","title":"Omaha, NE: Three-Day City Adventure","destination":"Omaha, NE","state":"NE","stateName":"Nebraska","region":"Eastern Nebraska","days":3,"tripType":"city adventure","interests":["family","museums","food","outdoors"],"budget":1000,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Home of the world's best zoo: deserts, jungles, and an aquarium under one roof.","overview":"Omaha's Henry Doorly Zoo is regularly voted the best in the world \u2014 the desert dome and jungle alone are worth the trip. But Omaha has much more: a gorgeous art-deco train station museum, a pedestrian bridge spanning the Missouri River into Iowa, and one of the Midwest's best food scenes. Three days gives you the zoo plus the city's other gems. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Explore the world's largest indoor desert at Henry Doorly Zoo","Walk across the Missouri River on the Bob Kerrey Bridge","Tour the art-deco Durham Museum","Wander 100 acres at Lauritzen Gardens","See historic aircraft at the SAC Aerospace Museum"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The zoo is enormous \u2014 plan a full day with rest breaks; the bridge walk suits all ages.","lat":41.26068,"lng":-95.94026,"itinerary":[{"day":1,"title":"Zoo Day","morning":{"stop":"Omaha's Henry Doorly Zoo and Aquarium","description":"Devote the whole day to the world's best zoo. Start at the Desert Dome \u2014 the largest indoor desert on Earth \u2014 then the Lied Jungle's rainforest, the aquarium's shark tunnel, and the gorilla valley. Arrive at opening; you'll need 6+ hours.","cost":"$31.95/adult, $23.95/child (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Zoo continued","description":"After lunch, hit the aquarium, the elephant family, and the children's adventure trails. The skyfari ride gives tired legs a break with a bird's-eye view of the whole zoo.","cost":"Included with admission (est.)","time":"1:30 PM \u2013 5:00 PM"},"evening":{"stop":"Old Market dinner","description":"Omaha's Old Market district \u2014 brick streets, galleries, and great restaurants \u2014 is perfect for dinner. The area is lively and walkable; kids love the street performers in summer.","cost":"$60\u2013$80 dinner for four (est.)","time":"6:00 PM \u2013 8:30 PM"}},{"day":2,"title":"Museums and the River","morning":{"stop":"The Durham Museum","description":"In the stunning 1931 art-deco Union Station, this museum brings Omaha's history to life: walk through a 1940s street, tour vintage train cars, and explore the hands-on kids' exhibits in the lower level.","cost":"$15/adult, $8/child (est.)","time":"10:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"Bob Kerrey Pedestrian Bridge","description":"Walk the 3,000-foot bridge spanning the Missouri River \u2014 you can stand in Nebraska and Iowa at the same time (there's a marker). The riverfront trails on both sides are great for biking.","cost":"Free (est.)","time":"2:00 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner in Benson","description":"The Benson neighborhood has Omaha's funkiest restaurants \u2014 great burgers, pizza, and ice cream. A more local, less touristy evening.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Gardens and Flight","morning":{"stop":"Lauritzen Gardens","description":"One hundred acres of botanical beauty: the rose garden, the woodland trails, and the fantastic children's garden with its treehouse village. The conservatory's tropical plants are lovely year-round.","cost":"$16/adult, $8/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Strategic Air Command & Aerospace Museum","description":"Drive 30 minutes to Ashland for this spectacular aircraft museum: an SR-71 Blackbird, B-52s, and space artifacts in two huge hangars. Kids can climb into cockpits and try the flight simulators.","cost":"$17/adult, $10/child (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Farewell steak dinner","description":"Omaha is steak country \u2014 end with a classic steakhouse dinner. The city's steakhouses are legendary and surprisingly family-friendly.","cost":"$80\u2013$100 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}}],"attractions":[{"name":"Omaha's Henry Doorly Zoo and Aquarium","description":"Regularly voted the world's best zoo: the Desert Dome (largest indoor desert on Earth), the Lied Jungle rainforest, a shark-tunnel aquarium, and huge elephant and gorilla habitats. A full-day, world-class experience.","officialUrl":"https://www.omahazoo.com","price":"$31.95/adult, $23.95/child (est.)","photos":["assets/midwest-west/omaha-ne-city/attr1-1.jpg","assets/midwest-west/omaha-ne-city/attr1-2.jpg","assets/midwest-west/omaha-ne-city/attr1-3.jpg","assets/midwest-west/omaha-ne-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Omaha%27s%20Henry%20Doorly%20Zoo%20and%20Aquarium%20Omaha%20NE"},{"name":"The Durham Museum","description":"Housed in the magnificent 1931 art-deco Union Station, with vintage train cars, a recreated 1940s street, and engaging regional history exhibits. The building alone \u2014 all marble and brass \u2014 is breathtaking.","officialUrl":"https://www.durhammuseum.org","price":"$15/adult, $8/child (est.)","photos":["assets/midwest-west/omaha-ne-city/attr2-1.jpg","assets/midwest-west/omaha-ne-city/attr2-2.jpg","assets/midwest-west/omaha-ne-city/attr2-3.jpg","assets/midwest-west/omaha-ne-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=The%20Durham%20Museum%20Omaha%20NE"},{"name":"Bob Kerrey Pedestrian Bridge","description":"A 3,000-foot cable-stayed bridge spanning the Missouri River between Nebraska and Iowa \u2014 stand in two states at once at the mid-point marker. The riverfront trails and parks on both ends are perfect for families.","officialUrl":"https://www.visitomaha.com","price":"Free (est.)","photos":["assets/midwest-west/omaha-ne-city/attr3-1.jpg","assets/midwest-west/omaha-ne-city/attr3-2.jpg","assets/midwest-west/omaha-ne-city/attr3-3.jpg","assets/midwest-west/omaha-ne-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bob%20Kerrey%20Pedestrian%20Bridge%20Omaha%20NE"},{"name":"Lauritzen Gardens","description":"A 100-acre botanical garden with a stunning rose garden, woodland trails, and one of the region's best children's gardens. The Marjorie K. Daugherty Conservatory brings the tropics to Nebraska year-round.","officialUrl":"https://www.lauritzengardens.org","price":"$16/adult, $8/child (est.)","photos":["assets/midwest-west/omaha-ne-city/attr4-1.jpg","assets/midwest-west/omaha-ne-city/attr4-2.jpg","assets/midwest-west/omaha-ne-city/attr4-3.jpg","assets/midwest-west/omaha-ne-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lauritzen%20Gardens%20Omaha%20NE"},{"name":"Strategic Air Command & Aerospace Museum","description":"Between Omaha and Lincoln, two massive hangars hold an SR-71 Blackbird, Cold War bombers, and space artifacts. Cockpit climbs and simulators make it a hit with kids who love big machines.","officialUrl":"https://www.sacmuseum.org","price":"$17/adult, $10/child (est.)","photos":["assets/midwest-west/omaha-ne-city/attr5-1.jpg","assets/midwest-west/omaha-ne-city/attr5-2.jpg","assets/midwest-west/omaha-ne-city/attr5-3.jpg","assets/midwest-west/omaha-ne-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Strategic%20Air%20Command%20%26%20Aerospace%20Museum%20Ashland%20NE"}],"restaurants":[{"name":"Block 16","detail":"Downtown's beloved gourmet burger-and-sandwich counter \u2014 creative, delicious, and perfect for a family lunch.","price":"$$"},{"name":"Ted & Wally's","detail":"The Old Market's famous homemade ice cream shop \u2014 wild flavors in a charming vintage setting.","price":"$"},{"name":"Lisa's Radial Cafe","detail":"An Omaha breakfast institution \u2014 huge portions of comfort food in a classic diner setting.","price":"$"}],"rainyDay":["The Durham Museum \u2014 art-deco grandeur and indoor exhibits","Strategic Air Command & Aerospace Museum \u2014 two huge indoor hangars","Omaha Children's Museum \u2014 hands-on play downtown"],"driveNotes":"Omaha sits on I-80 at the Nebraska-Iowa border. The zoo is south of downtown; the airport is 10 minutes north. Parking is easy everywhere except the Old Market on weekends. The SAC Museum in Ashland is a straight 30-minute shot west on I-80 \u2014 combine it with Lincoln if you're heading that way.","related":["lincoln-ne-city","des-moines-ia-city","kansas-city-mo-city"],"imageAsset":"assets/midwest-west/omaha-ne-city/hero.jpg"},{"id":"lincoln-ne-city","title":"Lincoln, NE: Three-Day Capital Getaway","destination":"Lincoln, NE","state":"NE","stateName":"Nebraska","region":"Eastern Nebraska","days":3,"tripType":"capital getaway","interests":["family","museums","outdoors","historical-sites"],"budget":800,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Nebraska's friendly capital: a tower capitol, a children's zoo, and Husker spirit everywhere.","overview":"Lincoln is one of the Midwest's most pleasant small capitals: a stunning art-deco capitol tower, a beloved children's zoo, gorgeous sunken gardens, and a university town's worth of energy. It's compact, affordable, and easy \u2014 a relaxed three days that pairs perfectly with Omaha an hour east. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Ride to the top of the Nebraska State Capitol tower","Feed giraffes at the Lincoln Children's Zoo","Stroll the floral Sunken Gardens","Meet Archie the mammoth at Morrill Hall","Hike and play at Pioneers Park"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 4+. The Capitol tower tour involves stairs; the zoo and gardens are perfect for all ages including toddlers.","lat":40.81362,"lng":-96.7073,"itinerary":[{"day":1,"title":"Capitol and Campus","morning":{"stop":"Nebraska State Capitol","description":"Tour America's most distinctive state capitol \u2014 a 400-foot art-deco tower topped with a 19-foot bronze Sower. The free guided tour covers the stunning mosaics and chambers; the observation deck offers a 20-mile view.","cost":"Free tours (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"University of Nebraska State Museum (Morrill Hall)","description":"On the UNL campus, meet Archie \u2014 the world's largest mounted mammoth \u2014 plus dinosaurs, fossils, and wildlife dioramas. The museum's hands-on discovery zone keeps younger kids engaged.","cost":"$10/adult, $5/child (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Downtown Haymarket dinner","description":"The historic Haymarket district \u2014 brick streets, warehouses-turned-restaurants \u2014 is great for dinner. In fall, the Husker buzz is electric; in summer, it's relaxed and fun.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Zoo and Gardens","morning":{"stop":"Lincoln Children's Zoo","description":"A gem of a small zoo designed for kids: feed giraffes, ride the train, meet red pandas, and splash in the play areas. It's intimate and uncrowded \u2014 families consistently rate it a favorite.","cost":"$14.95/adult, $11.95/child (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Sunken Gardens","description":"Across from the zoo, these terraced gardens explode with 30,000+ annual flowers, sculptures, and a reflecting pool. It's one of Nebraska's prettiest spots \u2014 bring a camera and let the kids run the lawns.","cost":"Free (est.)","time":"1:30 PM \u2013 3:30 PM"},"evening":{"stop":"Runza dinner","description":"You can't visit Nebraska without Runza \u2014 the iconic stuffed sandwich chain. Grab the Original Runza and frings (fries + onion rings) for a true Nebraska dinner.","cost":"$30\u2013$40 dinner for four (est.)","time":"5:00 PM \u2013 7:00 PM"}},{"day":3,"title":"Pioneers Park Day","morning":{"stop":"Pioneers Park Nature Center","description":"In this 668-acre park, the nature center's trails wind past bison, elk, and prairie dogs in large natural enclosures. The live-animal building and the prairie trails make a great morning.","cost":"Free (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Pioneers Park continued","description":"Picnic in the park, visit the prairie-style Daffodil Hill in spring, and let the kids play at the playgrounds. The park's sheer size means peaceful trails even on busy days.","cost":"Free; picnic $30\u2013$40 (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell in the Haymarket","description":"One last Haymarket dinner \u2014 try the local pizza or barbecue spots. Lincoln's easy pace makes for a gentle goodbye.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Nebraska State Capitol","description":"A 400-foot art-deco tower \u2014 utterly unlike any other state capitol \u2014 crowned by the bronze Sower. Free tours showcase the mosaics, murals, and chambers; the 14th-floor observatory has sweeping views.","officialUrl":"https://www.capitol.nebraska.gov","price":"Free tours (est.)","photos":["assets/midwest-west/lincoln-ne-city/attr1-1.jpg","assets/midwest-west/lincoln-ne-city/attr1-2.jpg","assets/midwest-west/lincoln-ne-city/attr1-3.jpg","assets/midwest-west/lincoln-ne-city/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Nebraska%20State%20Capitol%20Lincoln%20NE"},{"name":"Lincoln Children's Zoo","description":"A beloved small zoo built for young kids: giraffe feedings, a train ride, red pandas, and splash areas. Intimate, shady, and easy \u2014 many families prefer it to bigger zoos.","officialUrl":"https://www.lincolnzoo.org","price":"$14.95/adult, $11.95/child (est.)","photos":["assets/midwest-west/lincoln-ne-city/attr2-1.jpg","assets/midwest-west/lincoln-ne-city/attr2-2.jpg","assets/midwest-west/lincoln-ne-city/attr2-3.jpg","assets/midwest-west/lincoln-ne-city/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lincoln%20Children%27s%20Zoo%20Lincoln%20NE"},{"name":"Sunken Gardens","description":"Terraced gardens in the heart of Lincoln with 30,000+ flowers, sculptures, lily ponds, and lawns. A riot of color from spring through fall \u2014 and completely free.","officialUrl":"https://www.lincoln.ne.gov","price":"Free (est.)","photos":["assets/midwest-west/lincoln-ne-city/attr3-1.jpg","assets/midwest-west/lincoln-ne-city/attr3-2.jpg","assets/midwest-west/lincoln-ne-city/attr3-3.jpg","assets/midwest-west/lincoln-ne-city/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Sunken%20Gardens%20Lincoln%20NE"},{"name":"University of Nebraska State Museum","description":"In historic Morrill Hall: Archie the giant mammoth, dinosaurs, Nebraska wildlife dioramas, and a hands-on discovery center. The state's natural history in one engaging museum.","officialUrl":"https://www.museum.unl.edu","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/lincoln-ne-city/attr4-1.jpg","assets/midwest-west/lincoln-ne-city/attr4-2.jpg","assets/midwest-west/lincoln-ne-city/attr4-3.jpg","assets/midwest-west/lincoln-ne-city/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=University%20of%20Nebraska%20State%20Museum%20Lincoln%20NE"},{"name":"Pioneers Park Nature Center","description":"668 acres of prairie, woodland, and ponds with bison, elk, and prairie dogs in natural habitats. Miles of trails plus a nature center with live animals \u2014 Lincoln's wild backyard.","officialUrl":"https://www.lincoln.ne.gov","price":"Free (est.)","photos":["assets/midwest-west/lincoln-ne-city/attr5-1.jpg","assets/midwest-west/lincoln-ne-city/attr5-2.jpg","assets/midwest-west/lincoln-ne-city/attr5-3.jpg","assets/midwest-west/lincoln-ne-city/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pioneers%20Park%20Nature%20Center%20Lincoln%20NE"}],"restaurants":[{"name":"Runza","detail":"Nebraska's iconic stuffed-sandwich chain \u2014 the Original Runza (beef, cabbage, and onions in fresh-baked bread) is a must-try.","price":"$"},{"name":"Yia Yia's Pizza & Beer","detail":"A Lincoln favorite for creative pizzas and a huge beer list in a fun, casual setting near campus.","price":"$$"},{"name":"The Oven","detail":"Beloved Indian restaurant in the Haymarket \u2014 flavorful curries and fresh naan that please adventurous eaters.","price":"$$"}],"rainyDay":["University of Nebraska State Museum \u2014 mammoths and dinosaurs indoors","Nebraska State Capitol \u2014 free guided tours of the tower interiors","Lincoln Children's Museum \u2014 hands-on play downtown"],"driveNotes":"Lincoln is 1 hour west of Omaha on I-80 \u2014 the two cities pair perfectly. Downtown parking is easy and cheap; the Haymarket has ramps. Everything is within 10 minutes. On Husker home football Saturdays, the whole town fills up \u2014 book ahead or avoid.","related":["omaha-ne-city","kearney-ne-platte","topeka-ks-city"],"imageAsset":"assets/midwest-west/lincoln-ne-city/hero.jpg"},{"id":"scottsbluff-ne-history","title":"Scottsbluff, NE: Three-Day Frontier Adventure","destination":"Scottsbluff, NE","state":"NE","stateName":"Nebraska","region":"Nebraska Panhandle","days":3,"tripType":"frontier adventure","interests":["family","historical-sites","outdoors","nature","scenic"],"budget":750,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Walk in wagon-train footsteps: towering bluffs, Chimney Rock, and pioneer history.","overview":"The Nebraska Panhandle is where the Oregon, California, and Mormon Trails squeezed past towering rock formations \u2014 and Scottsbluff is the perfect base. Climb (by car and trail) the bluff that guided a quarter-million pioneers, see Chimney Rock rising from the prairie, and explore pioneer museums. It's a history-rich trip with big skies and zero crowds. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Drive the summit road at Scotts Bluff National Monument","See Chimney Rock rising from the prairie","Explore pioneer life at Legacy of the Plains Museum","Hike the pine-topped Wildcat Hills","Swim and boat at Lake Minatare"],"bestSeason":"April\u2013October","familyFriendly":"Best for ages 6+. The monument's trails are exposed with drop-offs \u2014 keep little ones close; the museums suit all ages.","lat":41.86219,"lng":-103.66274,"itinerary":[{"day":1,"title":"Scotts Bluff Day","morning":{"stop":"Scotts Bluff National Monument","description":"Start at the visitor center's excellent Oregon Trail exhibits, then drive the 1.6-mile summit road (or hike the trail) to the top of the 800-foot bluff. The view spans the North Platte Valley the pioneers crossed \u2014 and you can walk a stretch of the actual trail ruts.","cost":"$7/person, kids under 16 free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Legacy of the Plains Museum","description":"In nearby Gering, this museum's village of historic buildings \u2014 blacksmith shop, schoolhouse, homestead \u2014 brings pioneer life to life. Kids love the hands-on farm equipment and the covered-wagon displays.","cost":"$10/adult, $5/child (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Scottsbluff","description":"The downtown area has family-friendly steakhouses and Mexican restaurants. After dinner, drive back to the monument for sunset \u2014 the bluffs glow orange.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:30 PM"}},{"day":2,"title":"Chimney Rock and Wildcat Hills","morning":{"stop":"Chimney Rock National Historic Site","description":"Drive 25 minutes to the most famous landmark on the Oregon Trail \u2014 a 325-foot spire that told pioneers they were a quarter of the way to Oregon. The visitor center's exhibits and the short trail to the viewing area are excellent.","cost":"$5/adult, $3/child 5-18 (est.)","time":"9:00 AM \u2013 11:30 AM"},"afternoon":{"stop":"Wildcat Hills State Recreation Area","description":"Hike the pine-covered ridges south of Gering \u2014 the trails wind through ponderosa forest with prairie views. The nature center has great exhibits on the area's wildlife, and the overlook is spectacular.","cost":"Nebraska park permit $8/day (est.)","time":"12:30 PM \u2013 4:00 PM"},"evening":{"stop":"Dinner in Gering","description":"Gering's small downtown has cozy family restaurants. An early night \u2014 or a sunset drive through the Wildcat Hills for golden-hour photos.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":3,"title":"Lake Day and Farewell","morning":{"stop":"Lake Minatare State Recreation Area","description":"Nebraska's unexpected beach: swim, boat, or just play at the lake 15 minutes northeast of Scottsbluff. The sandy shoreline and the little lighthouse make it a fun, surprising morning.","cost":"Nebraska park permit $8/day (est.)","time":"9:30 AM \u2013 12:30 PM"},"afternoon":{"stop":"Riverside Park and zoo","description":"Back in Scottsbluff, visit Riverside Park \u2014 home to a small free zoo (the Riverside Discovery Center) with bison, big cats, and primates. The park's playgrounds and trails fill the afternoon.","cost":"Free park; zoo $8/adult, $5/child (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell dinner","description":"One last Panhandle dinner \u2014 the region's steakhouses are excellent. Watch the sun set behind the bluffs from anywhere in town.","cost":"$55\u2013$75 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Scotts Bluff National Monument","description":"The 800-foot bluff that guided 250,000+ pioneers west. Drive or hike to the summit, walk actual Oregon Trail ruts, and explore the superb visitor center. The valley views are immense.","officialUrl":"https://www.nps.gov/scbl","price":"$7/person, kids under 16 free (est.)","photos":["assets/midwest-west/scottsbluff-ne-history/attr1-1.jpg","assets/midwest-west/scottsbluff-ne-history/attr1-2.jpg","assets/midwest-west/scottsbluff-ne-history/attr1-3.jpg","assets/midwest-west/scottsbluff-ne-history/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Scotts%20Bluff%20National%20Monument%20Gering%20NE"},{"name":"Chimney Rock National Historic Site","description":"The iconic 325-foot spire that marked a quarter of the Oregon Trail journey. The visitor center tells the pioneer story beautifully, and the viewing trail frames the rock against huge skies.","officialUrl":"https://history.nebraska.gov/rock/","price":"$5/adult, $3/child 5-18 (est.)","photos":["assets/midwest-west/scottsbluff-ne-history/attr2-1.jpg","assets/midwest-west/scottsbluff-ne-history/attr2-2.jpg","assets/midwest-west/scottsbluff-ne-history/attr2-3.jpg","assets/midwest-west/scottsbluff-ne-history/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chimney%20Rock%20National%20Historic%20Site%20Bayard%20NE"},{"name":"Legacy of the Plains Museum","description":"A village of historic buildings \u2014 homestead, schoolhouse, blacksmith shop \u2014 plus superb exhibits on Panhandle agriculture and pioneer life. The covered-wagon collection is a highlight.","officialUrl":"https://www.legacyoftheplains.org","price":"$10/adult, $5/child (est.)","photos":["assets/midwest-west/scottsbluff-ne-history/attr3-1.jpg","assets/midwest-west/scottsbluff-ne-history/attr3-2.jpg","assets/midwest-west/scottsbluff-ne-history/attr3-3.jpg","assets/midwest-west/scottsbluff-ne-history/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Legacy%20of%20the%20Plains%20Museum%20Gering%20NE"},{"name":"Wildcat Hills State Recreation Area","description":"Ponderosa-pine ridges rising from the prairie, with trails to dramatic overlooks and a nature center full of wildlife exhibits. The contrast of pine forest and open prairie is striking.","officialUrl":"https://www.outdoornebraska.gov","price":"Nebraska park permit $8/day (est.)","photos":["assets/midwest-west/scottsbluff-ne-history/attr4-1.jpg","assets/midwest-west/scottsbluff-ne-history/attr4-2.jpg","assets/midwest-west/scottsbluff-ne-history/attr4-3.jpg","assets/midwest-west/scottsbluff-ne-history/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wildcat%20Hills%20State%20Recreation%20Area%20Gering%20NE"},{"name":"Lake Minatare State Recreation Area","description":"A surprising prairie lake with a sandy beach, boating, and even a small lighthouse. Swim, picnic, and watch pelicans \u2014 an easy, fun lake day 15 minutes from Scottsbluff.","officialUrl":"https://www.outdoornebraska.gov","price":"Nebraska park permit $8/day (est.)","photos":["assets/midwest-west/scottsbluff-ne-history/attr5-1.jpg","assets/midwest-west/scottsbluff-ne-history/attr5-2.jpg","assets/midwest-west/scottsbluff-ne-history/attr5-3.jpg","assets/midwest-west/scottsbluff-ne-history/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake%20Minatare%20State%20Recreation%20Area%20Minatare%20NE"}],"restaurants":[{"name":"The Steel Grill","detail":"Gering's beloved steakhouse \u2014 famous steak nachos, local beef, and a fun sports-bar atmosphere the whole family enjoys.","price":"$$"},{"name":"Runza","detail":"Nebraska's iconic stuffed-sandwich chain \u2014 the Original Runza is the taste of the state.","price":"$"},{"name":"El Torito Grill","detail":"A family-friendly Mexican grill in Gering with generous portions and a welcoming vibe.","price":"$$"}],"rainyDay":["Legacy of the Plains Museum \u2014 pioneer buildings and indoor exhibits","Scotts Bluff National Monument visitor center \u2014 Oregon Trail films and exhibits","West Nebraska Arts Center and downtown Scottsbluff shops"],"driveNotes":"Scottsbluff is in the far western Panhandle \u2014 7 hours from Omaha, 3 hours from Cheyenne. The drives between sights are short (everything within 30 minutes), but getting here is the journey. Fill up gas; services thin out on the prairie highways. Nebraska park permits are $8/day or $45/year (est.).","related":["dodge-city-ks-western","sandhills-ne-nature","kearney-ne-platte"],"imageAsset":"assets/midwest-west/scottsbluff-ne-history/hero.jpg"},{"id":"sandhills-ne-nature","title":"Nebraska Sandhills, NE: Three-Day Nature Adventure","destination":"Valentine, NE","state":"NE","stateName":"Nebraska","region":"Nebraska Sandhills","days":3,"tripType":"nature adventure","interests":["family","outdoors","nature","scenic"],"budget":750,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days, excluding lodging upgrades.","tagline":"Grass-covered dunes, a waterfall in the prairie, and some of America's darkest skies.","overview":"The Nebraska Sandhills are one of the world's great grasslands \u2014 19,000 square miles of dunes held in place by grass, with spring-fed rivers, waterfalls, and wildlife refuges. Base in the cowboy town of Valentine to float the Niobrara River, see Nebraska's tallest waterfall, and stargaze under some of the darkest skies in America. This is a trip for families who want real wilderness without the crowds. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["See 70-foot Smith Falls, Nebraska's tallest waterfall","Float or canoe the Niobrara National Scenic River","Watch bison at Fort Niobrara National Wildlife Refuge","Stargaze under dark skies at Merritt Reservoir","Spot prairie chickens and cranes in the Sandhills"],"bestSeason":"May\u2013September","familyFriendly":"Best for ages 6+. River floating suits confident swimmers with life jackets; the falls and refuges are great for all ages.","lat":42.87384,"lng":-100.55062,"itinerary":[{"day":1,"title":"Waterfall and Refuge","morning":{"stop":"Smith Falls State Park","description":"Drive 15 minutes east of Valentine to Nebraska's tallest waterfall \u2014 70 feet of spring-fed water pouring over a sandstone cliff. The boardwalk trail is short and easy, and you can wade in the plunge pool on hot days.","cost":"Nebraska park permit $8/day (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Fort Niobrara National Wildlife Refuge","description":"Drive the refuge's auto tour loop past bison, elk, and prairie dogs. The short trail to Fort Falls (a smaller waterfall) is lovely, and the wildlife viewing from the car suits all ages.","cost":"Free (est.)","time":"1:30 PM \u2013 4:30 PM"},"evening":{"stop":"Dinner in Valentine","description":"Valentine is a classic cowboy town \u2014 have dinner at a local steakhouse or caf\u00e9, then walk the historic downtown. The town's frontier feel is half the fun.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Niobrara River Day","morning":{"stop":"Niobrara National Scenic River float","description":"The trip's centerpiece: float the spring-fed Niobrara past waterfalls, cliffs, and ponderosa pines. Outfitters rent canoes, kayaks, and tubes; the popular Smith Falls-to-Berry Bridge stretch takes 3\u20134 hours with swim stops.","cost":"$40\u2013$60/person tube/canoe rental (est.)","time":"9:00 AM \u2013 1:00 PM"},"afternoon":{"stop":"River beaches and waterfalls","description":"Pull over at sandy beaches to swim, and hike the short trails to riverside waterfalls like Stairstep Falls. The Niobrara's clear, cool water is perfect on a hot Sandhills day.","cost":"Included with rental (est.)","time":"1:00 PM \u2013 4:00 PM"},"evening":{"stop":"Merritt Reservoir stargazing","description":"Drive 30 minutes south to Merritt Reservoir \u2014 an International Dark Sky Park. As the sun sets over the water, the stars come out in staggering numbers. Bring blankets and lie back.","cost":"Nebraska park permit $8/day (est.)","time":"8:00 PM \u2013 10:30 PM"}},{"day":3,"title":"Sandhills Wildlife Day","morning":{"stop":"Valentine National Wildlife Refuge","description":"Explore 71,000 acres of Sandhills lakes and prairie: drive the auto tour, hike the short trails, and watch for pelicans, herons, and (in season) thousands of migrating waterfowl. It's gloriously empty.","cost":"Free (est.)","time":"9:00 AM \u2013 12:30 PM"},"afternoon":{"stop":"Cowboy Trail or downtown Valentine","description":"Bike or walk a stretch of the Cowboy Trail \u2014 Nebraska's rails-to-trails path \u2014 or explore Valentine's shops and the Cherry County Historical Society museum. A relaxed final afternoon.","cost":"Free (est.)","time":"1:30 PM \u2013 4:00 PM"},"evening":{"stop":"Farewell dinner","description":"One last Sandhills dinner in Valentine. If the sky is clear, step outside after dark \u2014 you'll never forget these stars.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}}],"attractions":[{"name":"Smith Falls State Park","description":"Nebraska's tallest waterfall: 70 feet of spring water cascading over sandstone into the Niobrara River. A short boardwalk trail leads to the falls, with wading and picnicking at the base.","officialUrl":"https://www.outdoornebraska.gov","price":"Nebraska park permit $8/day (est.)","photos":["assets/midwest-west/sandhills-ne-nature/attr1-1.jpg","assets/midwest-west/sandhills-ne-nature/attr1-2.jpg","assets/midwest-west/sandhills-ne-nature/attr1-3.jpg","assets/midwest-west/sandhills-ne-nature/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Smith%20Falls%20State%20Park%20Valentine%20NE"},{"name":"Niobrara National Scenic River","description":"76 miles of spring-fed river through the Sandhills: waterfalls, limestone cliffs, and ponderosa pines. Float by tube, canoe, or kayak past scenery you'd never expect in Nebraska.","officialUrl":"https://www.nps.gov/niob","price":"Free; outfitter rentals $40\u2013$60/person (est.)","photos":["assets/midwest-west/sandhills-ne-nature/attr2-1.jpg","assets/midwest-west/sandhills-ne-nature/attr2-2.jpg","assets/midwest-west/sandhills-ne-nature/attr2-3.jpg","assets/midwest-west/sandhills-ne-nature/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Niobrara%20National%20Scenic%20River%20Valentine%20NE"},{"name":"Fort Niobrara National Wildlife Refuge","description":"19,000 acres of Sandhills prairie with bison, elk, prairie dogs, and the scenic Fort Falls. Drive the auto tour, hike the short trails, and experience the Sandhills' wild heart.","officialUrl":"https://www.fws.gov/refuge/fort-niobrara","price":"Free (est.)","photos":["assets/midwest-west/sandhills-ne-nature/attr3-1.jpg","assets/midwest-west/sandhills-ne-nature/attr3-2.jpg","assets/midwest-west/sandhills-ne-nature/attr3-3.jpg","assets/midwest-west/sandhills-ne-nature/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort%20Niobrara%20National%20Wildlife%20Refuge%20Valentine%20NE"},{"name":"Merritt Reservoir State Recreation Area","description":"A 2,900-acre Sandhills reservoir and International Dark Sky Park: boat, fish, and swim by day; stargaze under some of America's darkest skies by night. The annual Star Party draws astronomers nationwide.","officialUrl":"https://www.outdoornebraska.gov","price":"Nebraska park permit $8/day (est.)","photos":["assets/midwest-west/sandhills-ne-nature/attr4-1.jpg","assets/midwest-west/sandhills-ne-nature/attr4-2.jpg","assets/midwest-west/sandhills-ne-nature/attr4-3.jpg","assets/midwest-west/sandhills-ne-nature/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Merritt%20Reservoir%20State%20Recreation%20Area%20Valentine%20NE"},{"name":"Valentine National Wildlife Refuge","description":"71,000 acres of Sandhills dunes, lakes, and prairie \u2014 one of America's great wildlife refuges. Drive the auto tour past lakes full of pelicans and herons; in migration season, the birdlife is staggering.","officialUrl":"https://www.fws.gov/refuge/valentine","price":"Free (est.)","photos":["assets/midwest-west/sandhills-ne-nature/attr5-1.jpg","assets/midwest-west/sandhills-ne-nature/attr5-2.jpg","assets/midwest-west/sandhills-ne-nature/attr5-3.jpg","assets/midwest-west/sandhills-ne-nature/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Valentine%20National%20Wildlife%20Refuge%20Valentine%20NE"}],"restaurants":[{"name":"Bulldoggers BBQ","detail":"Valentine's beloved barbecue joint on Main Street \u2014 smoked meats and hearty sides in a fun cowboy-town setting.","price":"$$"},{"name":"Coachlight Inn","detail":"A classic small-town caf\u00e9 serving breakfast all day, burgers, and homemade pie \u2014 the locals' favorite.","price":"$"},{"name":"The Bunkhouse and Lounge","detail":"A casual Valentine spot for burgers, sandwiches, and a laid-back Sandhills evening.","price":"$$"}],"rainyDay":["Cherry County Historical Society Museum \u2014 Sandhills history in Valentine","Niobrara National Scenic River visitor center \u2014 exhibits on the river","Valentine's downtown shops and the historic theater"],"driveNotes":"Valentine is remote \u2014 5 hours from Omaha, 4 from Rapid City. Fill up gas whenever you can; the Sandhills have long empty stretches. Cell service is spotty \u2014 download offline maps. Book river outfitters ahead for summer weekends; the Niobrara is busiest on Saturdays.","related":["scottsbluff-ne-history","flint-hills-ks-prairie","kearney-ne-platte"],"imageAsset":"assets/midwest-west/sandhills-ne-nature/hero.jpg"},{"id":"kearney-ne-platte","title":"Kearney, NE: Two-Day Platte River Getaway","destination":"Kearney, NE","state":"NE","stateName":"Nebraska","region":"Central Nebraska","days":2,"tripType":"river getaway","interests":["family","historical-sites","museums","outdoors"],"budget":500,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days, excluding lodging upgrades.","tagline":"Where the wagons crossed: a monument over the interstate, a frontier fort, and crane country.","overview":"Kearney sits on the Platte River where half a million pioneers passed west \u2014 and where half a million sandhill cranes still stop each spring. The Archway monument spanning I-80 tells the westward story brilliantly, Fort Kearny brings the frontier to life, and Yanney Park gives kids room to run. It's a perfect two-day stop or a weekend of its own. All prices and hours below are estimates \u2014 verify before you go, as seasonal schedules change.","highlights":["Walk through the Archway monument over I-80","Explore the frontier fort at Fort Kearny","Climb the tower at Yanney Heritage Park","Ride the rails at the Trails & Rails Museum","See Nebraska art at MONA"],"bestSeason":"March\u2013October","familyFriendly":"Best for ages 5+. The Archway's self-guided audio tour engages ages 8+; Yanney Park and the fort suit all ages.","lat":40.70047,"lng":-99.08347,"itinerary":[{"day":1,"title":"Archway and Fort","morning":{"stop":"The Archway","description":"Start at the extraordinary monument spanning I-80: walk through 170 years of westward expansion \u2014 from Mormon handcarts to the interstate \u2014 via an excellent self-guided audio tour. The view of the highway from inside is thrilling for kids.","cost":"$15/adult, $8/child (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Fort Kearny State Historical Park","description":"Drive 15 minutes southeast to the 1848 frontier fort that protected Oregon Trail travelers. Tour the reconstructed stockade, blacksmith shop, and interpreters' demonstrations; the visitor center film sets the scene.","cost":"Nebraska park permit $8/day (est.)","time":"1:00 PM \u2013 3:30 PM"},"evening":{"stop":"Dinner downtown","description":"Kearney's downtown has family-friendly brewpubs and restaurants. Try Thunderhead Brewing's wood-fired pizza \u2014 Nebraska's first craft brewery welcomes kids.","cost":"$50\u2013$70 dinner for four (est.)","time":"5:30 PM \u2013 8:00 PM"}},{"day":2,"title":"Parks and Museums","morning":{"stop":"Yanney Heritage Park","description":"This 80-acre park is Kearney's gem: climb the 30-foot observation tower, walk the lake trails, and let the kids loose on the innovative playgrounds. The gardens and public art make it beautiful, not just functional.","cost":"Free (est.)","time":"9:30 AM \u2013 12:00 PM"},"afternoon":{"stop":"Trails & Rails Museum","description":"The Buffalo County Historical Society's museum village: historic buildings, vintage rail cars you can climb through, and exhibits on the railroad that built Kearney. Train-loving kids will be thrilled.","cost":"$8/adult, $4/child (est.)","time":"1:00 PM \u2013 3:00 PM"},"evening":{"stop":"Museum of Nebraska Art and farewell","description":"End at MONA, the state's official art collection, in a beautiful historic building \u2014 free and surprisingly engaging for kids. Then a farewell Runza dinner before hitting I-80.","cost":"Free museum; dinner $30\u2013$40 (est.)","time":"3:30 PM \u2013 6:30 PM"}}],"attractions":[{"name":"The Archway","description":"The Great Platte River Road Archway Monument: a stunning structure spanning I-80 that walks you through 170 years of westward migration. The self-guided audio tour \u2014 from handcarts to highways \u2014 is superb.","officialUrl":"https://www.archway.org","price":"$15/adult, $8/child (est.)","photos":["assets/midwest-west/kearney-ne-platte/attr1-1.jpg","assets/midwest-west/kearney-ne-platte/attr1-2.jpg","assets/midwest-west/kearney-ne-platte/attr1-3.jpg","assets/midwest-west/kearney-ne-platte/attr1-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=The%20Archway%20Kearney%20NE"},{"name":"Fort Kearny State Historical Park","description":"The 1848 frontier fort that guarded Oregon Trail travelers: reconstructed stockade, parade grounds, and living-history demonstrations. The visitor center's exhibits tell the fort's crucial story.","officialUrl":"https://www.outdoornebraska.gov","price":"Nebraska park permit $8/day (est.)","photos":["assets/midwest-west/kearney-ne-platte/attr2-1.jpg","assets/midwest-west/kearney-ne-platte/attr2-2.jpg","assets/midwest-west/kearney-ne-platte/attr2-3.jpg","assets/midwest-west/kearney-ne-platte/attr2-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort%20Kearny%20State%20Historical%20Park%20Kearney%20NE"},{"name":"Yanney Heritage Park","description":"Eighty acres of lake, trails, gardens, and one of Nebraska's best playgrounds \u2014 plus a 30-foot observation tower with river views. Kearney's favorite outdoor gathering place.","officialUrl":"https://www.yanneypark.org","price":"Free (est.)","photos":["assets/midwest-west/kearney-ne-platte/attr3-1.jpg","assets/midwest-west/kearney-ne-platte/attr3-2.jpg","assets/midwest-west/kearney-ne-platte/attr3-3.jpg","assets/midwest-west/kearney-ne-platte/attr3-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Yanney%20Heritage%20Park%20Kearney%20NE"},{"name":"Trails & Rails Museum","description":"The Buffalo County Historical Society's village of historic buildings and vintage rail equipment. Climb through cabooses and passenger cars, tour the pioneer buildings, and learn how the railroad built the Platte Valley.","officialUrl":"https://www.bchs.us","price":"$8/adult, $4/child (est.)","photos":["assets/midwest-west/kearney-ne-platte/attr4-1.jpg","assets/midwest-west/kearney-ne-platte/attr4-2.jpg","assets/midwest-west/kearney-ne-platte/attr4-3.jpg","assets/midwest-west/kearney-ne-platte/attr4-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Trails%20%26%20Rails%20Museum%20Kearney%20NE"},{"name":"Museum of Nebraska Art","description":"The state's official art collection in a handsome historic building: 5,000+ works by Nebraska artists, from frontier landscapes to contemporary pieces. Free, and the family guides make it kid-friendly.","officialUrl":"https://www.mona.unk.edu","price":"Free (est.)","photos":["assets/midwest-west/kearney-ne-platte/attr5-1.jpg","assets/midwest-west/kearney-ne-platte/attr5-2.jpg","assets/midwest-west/kearney-ne-platte/attr5-3.jpg","assets/midwest-west/kearney-ne-platte/attr5-4.jpg"],"mapsUrl":"https://www.google.com/maps/search/?api=1&query=Museum%20of%20Nebraska%20Art%20Kearney%20NE"}],"restaurants":[{"name":"Thunderhead Brewing","detail":"Nebraska's first craft brewery \u2014 wood-fired pizzas, calzones, and house-brewed root beer in a kid-friendly downtown taproom.","price":"$$"},{"name":"Cunningham's Journal","detail":"A lively downtown gastropub in a historic building \u2014 great burgers, live music, and a fun family atmosphere.","price":"$$"},{"name":"Runza","detail":"Nebraska's iconic stuffed-sandwich chain \u2014 the Original Runza is the essential Nebraska taste.","price":"$"}],"rainyDay":["The Archway \u2014 the entire experience is indoors over the interstate","Museum of Nebraska Art \u2014 free galleries in a historic building","Trails & Rails Museum \u2014 historic buildings and rail cars with covered areas"],"driveNotes":"Kearney is 2 hours west of Omaha on I-80 \u2014 the classic halfway stop across Nebraska. The Archway literally spans the interstate at exit 275; you can't miss it. Everything else is within 10 minutes. In March, the sandhill crane migration nearby is one of America's great wildlife spectacles \u2014 book ahead.","related":["lincoln-ne-city","scottsbluff-ne-history","sandhills-ne-nature"],"imageAsset":"assets/midwest-west/kearney-ne-platte/hero.jpg"}];
